function FoodMedSafetyChecker({ lang }) {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("food"); // "food" ou "med" — un choix obligatoire, pas de "Tous"

  const L = lang === "fr"
    ? {
        title: "Aliments & médicaments : est-ce sécuritaire ?", subtitle: "Choisissez aliment ou médicament, puis écrivez son nom pour voir son statut.",
        placeholder: "Ex. brie, ibuprofène, sushi…", food: "Aliment", med: "Médicament",
        avoid: "À éviter", limit: "À limiter", safe: "Sécuritaire",
        prompt: "Écrivez un nom ci-dessus pour voir son statut.",
        noResults: "Aucun résultat pour ce nom — vous pouvez aussi demander à Novaris, notre assistante virtuelle, pour une question plus précise.",
        disclaimer: "Informations générales seulement, à titre indicatif — chaque situation est différente. Confirmez toujours avec votre professionnel de la santé ou votre pharmacien avant de prendre une décision.",
      }
    : lang === "es"
    ? {
        title: "Alimentos y medicamentos: ¿es seguro?", subtitle: "Elige alimento o medicamento, luego escribe su nombre para ver su estado.",
        placeholder: "Ej. brie, ibuprofeno, sushi…", food: "Alimento", med: "Medicamento",
        avoid: "Evitar", limit: "Limitar", safe: "Seguro",
        prompt: "Escribe un nombre arriba para ver su estado.",
        noResults: "Sin resultados para ese nombre — también puedes preguntarle a Novaris, nuestra asistente virtual, para una pregunta más específica.",
        disclaimer: "Solo información general, a título indicativo — cada situación es diferente. Confirma siempre con tu profesional de la salud o farmacéutico antes de tomar una decisión.",
      }
    : {
        title: "Foods & medications: is it safe?", subtitle: "Choose food or medication, then type its name to see its status.",
        placeholder: "E.g. brie, ibuprofen, sushi…", food: "Food", med: "Medication",
        avoid: "Avoid", limit: "Limit", safe: "Safe",
        prompt: "Type a name above to see its status.",
        noResults: "No results for that name — you can also ask Novaris, our virtual assistant, for a more specific question.",
        disclaimer: "General information only, for guidance — every situation is different. Always confirm with your healthcare provider or pharmacist before making a decision.",
      };

  const statusMeta = {
    avoid: { color: "#B3261E", bg: "#FDECEA", label: L.avoid, emoji: "❌" },
    limit: { color: "#9C6B12", bg: "#FBF3E4", label: L.limit, emoji: "⚠️" },
    safe: { color: "#3F6B3E", bg: "#F0F5EC", label: L.safe, emoji: "✅" },
  };

  const q = query.trim().toLowerCase();
  const results = q.length < 2 ? [] : FOOD_MED_SAFETY_ITEMS
    .filter((it) => it.category === category)
    .filter((it) => (it.name[lang] || it.name.fr).toLowerCase().includes(q))
    .sort((a, b) => (a.name[lang] || a.name.fr).localeCompare(b.name[lang] || b.name.fr));

  const inputStyle = { width: "100%", padding: "11px 14px 11px 38px", borderRadius: 12, border: `1px solid ${COLORS.line}`, fontSize: 13.5, boxSizing: "border-box" };

  return (
    <Card style={{ marginBottom: 18 }}>
      <h3 style={{ margin: "0 0 4px", fontSize: 15, fontWeight: 800, color: COLORS.teal }}>{L.title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 12, color: COLORS.muted, lineHeight: 1.5 }}>{L.subtitle}</p>

      <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
        {[["food", L.food], ["med", L.med]].map(([key, label]) => (
          <button key={key} onClick={() => setCategory(key)} style={{
            flex: 1, padding: "8px", borderRadius: 10, cursor: "pointer", fontWeight: 700, fontSize: 12,
            border: `1px solid ${category === key ? COLORS.teal : COLORS.line}`,
            background: category === key ? COLORS.teal : "#fff", color: category === key ? "#fff" : COLORS.text,
          }}>{label}</button>
        ))}
      </div>

      <div style={{ position: "relative", marginBottom: 14 }}>
        <Search size={16} color={COLORS.muted} style={{ position: "absolute", left: 13, top: "50%", transform: "translateY(-50%)" }} />
        <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={L.placeholder} style={inputStyle} />
      </div>

      {q.length < 2 ? (
        <p style={{ fontSize: 12.5, color: COLORS.muted, textAlign: "center", padding: "10px 8px", fontStyle: "italic" }}>{L.prompt}</p>
      ) : results.length === 0 ? (
        <p style={{ fontSize: 12.5, color: COLORS.muted, textAlign: "center", padding: "16px 8px", fontStyle: "italic" }}>{L.noResults}</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {results.map((it) => {
            const sm = statusMeta[it.status];
            return (
              <div key={it.id} style={{ background: sm.bg, borderRadius: 12, padding: "10px 13px", borderLeft: `4px solid ${sm.color}` }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 }}>
                  <span style={{ fontWeight: 700, fontSize: 13, color: COLORS.text }}>{it.name[lang] || it.name.fr}</span>
                  <span style={{
                    flexShrink: 0, fontSize: 10.5, fontWeight: 800, color: sm.color, background: "#fff",
                    borderRadius: 999, padding: "2px 9px", whiteSpace: "nowrap",
                  }}>{sm.emoji} {sm.label}</span>
                </div>
                <p style={{ margin: "4px 0 0", fontSize: 12, color: COLORS.muted, lineHeight: 1.45 }}>{it.note[lang] || it.note.fr}</p>
              </div>
            );
          })}
        </div>
      )}

      <p style={{ fontSize: 11, color: COLORS.muted, lineHeight: 1.5, marginTop: 14, marginBottom: 0 }}>{L.disclaimer}</p>
    </Card>
  );
}

function FoodsToAvoidCard({ lang }) {
  const L = lang === "fr"
    ? { title: "Aliments à éviter durant la grossesse", subtitle: "Ces aliments comportent un risque réel pour vous ou le bébé — mieux vaut les éviter complètement pendant la grossesse." }
    : lang === "es"
    ? { title: "Alimentos a evitar durante el embarazo", subtitle: "Estos alimentos representan un riesgo real para ti o el bebé — es mejor evitarlos por completo durante el embarazo." }
    : { title: "Foods to avoid during pregnancy", subtitle: "These foods carry a real risk to you or baby — best avoided entirely during pregnancy." };
  return <AvoidFoodsCard lang={lang} title={L.title} subtitle={L.subtitle} items={FOODS_TO_AVOID} />;
}

function FoodsToFavorCard({ lang }) {
  const L = lang === "fr"
    ? { title: "Aliments à privilégier durant la grossesse", subtitle: "Ces aliments apportent les nutriments les plus importants pour vous et le développement de bébé — à intégrer régulièrement à votre menu." }
    : lang === "es"
    ? { title: "Alimentos a privilegiar durante el embarazo", subtitle: "Estos alimentos aportan los nutrientes más importantes para ti y el desarrollo del bebé — vale la pena incluirlos regularmente en tu menú." }
    : { title: "Foods to favor during pregnancy", subtitle: "These foods provide the nutrients most important for you and baby's development — worth including regularly in your meals." };
  return <AvoidFoodsCard lang={lang} title={L.title} subtitle={L.subtitle} items={FOODS_TO_FAVOR} color={COLORS.sage} bg="#F0F5EC" Icon={Check} />;
}

function FertilityFoodsToAvoidCard({ lang }) {
  const L = lang === "fr"
    ? { title: "Aliments à limiter pour la fertilité", subtitle: "Ces aliments, en excès, peuvent nuire à la fertilité chez la femme comme chez l'homme — à limiter en période de conception active." }
    : lang === "es"
    ? { title: "Alimentos a limitar para la fertilidad", subtitle: "Estos alimentos, en exceso, pueden afectar la fertilidad tanto en la mujer como en el hombre — vale la pena limitarlos durante la búsqueda activa de embarazo." }
    : { title: "Foods to limit for fertility", subtitle: "In excess, these foods may hinder fertility in both women and men — worth limiting while actively trying to conceive." };
  return <AvoidFoodsCard lang={lang} title={L.title} subtitle={L.subtitle} items={FERTILITY_FOODS_TO_AVOID} />;
}

