function WeeklyMilestoneTable({ lang }) {
  const L = lang === "fr"
    ? { title: "Ce qui se passe chaque semaine", subtitle: "Un aperçu rapide du développement de bébé, semaine après semaine.", week: "Semaine" }
    : lang === "es"
    ? { title: "Lo que sucede cada semana", subtitle: "Un vistazo rápido al desarrollo del bebé, semana tras semana.", week: "Semana" }
    : { title: "What's happening each week", subtitle: "A quick look at baby's development, week by week.", week: "Week" };

  const palette = [COLORS.pink, COLORS.ochre, COLORS.sage, COLORS.blue];
  // 10 illustrations (fournies par Marilyne) réparties sur 40 semaines — chaque image représente
  // 4 semaines consécutives (semaines 1-4 → image 0, 5-8 → image 1, ..., 37-40 → image 9).
  const imageForWeek = (w) => FETUS_STAGE_IMAGES[Math.min(9, Math.max(0, Math.ceil(w / 4) - 1))];

  return (
    <Card style={{ marginBottom: 18, borderTop: `4px solid ${COLORS.blue}`, background: "#FDFEFF" }}>
      <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 18, fontWeight: 700, color: COLORS.teal }}>{L.title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 12.5, color: COLORS.muted }}>{L.subtitle}</p>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 460, overflowY: "auto" }}>
        {WEEKLY_MILESTONES.map((row, i) => {
          const c = palette[i % palette.length];
          return (
            <div key={row.w} style={{
              display: "flex", alignItems: "center", gap: 12, padding: "8px 10px", borderRadius: 10,
              background: i % 2 ? `${c}14` : "transparent",
            }}>
              <div style={{
                width: 46, height: 46, borderRadius: 12, flexShrink: 0, background: "#fff",
                boxShadow: "0 2px 6px rgba(47,72,88,0.1)", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden",
              }}>
                <img src={imageForWeek(row.w)} alt="" style={{ width: 38, height: 38, objectFit: "contain" }} />
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 10.5, fontWeight: 800, color: c, textTransform: "uppercase", letterSpacing: "0.04em", marginBottom: 1 }}>
                  {L.week} {row.w}
                </div>
                <div style={{ fontSize: 12.5, color: COLORS.text, lineHeight: 1.4 }}>{row[lang] || row.fr}</div>
              </div>
            </div>
          );
        })}
      </div>
    </Card>
  );
}

// Petit badge réutilisable "bébé a la taille de..." avec illustration + poids, affiché dans la
// bulle d'accueil (statut membre), la bulle de profil (visible même en statut non-membre) et le
// résumé de grossesse — toujours basé sur la même donnée (PREGNANCY_WEEKS) pour rester cohérent.
function PregnancyFruitBadge({ weeks, lang, tone = "light" }) {
  const match = getClosestPregnancyWeek(weeks);
  if (!match) return null;
  const L = lang === "fr" ? { compareTo: "à peu près la taille de" } : lang === "es" ? { compareTo: "aproximadamente del tamaño de" } : { compareTo: "about the size of" };
  const light = tone === "light";
  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 12,
      background: light ? "#fff" : "rgba(255,255,255,0.22)",
      borderRadius: 16, padding: "10px 14px",
      boxShadow: light ? "0 2px 8px rgba(47,72,88,0.08)" : "none",
    }}>
      <div style={{
        width: 46, height: 46, borderRadius: 12, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
        background: light ? COLORS.cream : "rgba(255,255,255,0.18)",
      }}>
        <Illustration type={match.icon} size={30} />
      </div>
      <div style={{ minWidth: 0 }}>
        <p style={{ margin: 0, fontSize: 11.5, fontWeight: 700, color: light ? COLORS.muted : "#fff", opacity: light ? 1 : 0.9 }}>{L.compareTo}</p>
        <p style={{ margin: "1px 0 0", fontSize: 14, fontWeight: 800, color: light ? COLORS.teal : "#fff" }}>{match.compare[lang]}</p>
        <p style={{ margin: "1px 0 0", fontSize: 12, fontWeight: 700, color: light ? COLORS.ochre : "#fff", opacity: light ? 1 : 0.95 }}>{match.weight[lang]}</p>
      </div>
    </div>
  );
}

/* ---------------- DAILY TRACKER (feeding, sleep, diaper, kicks, contractions) ---------------- */
function formatDuration(ms, lang) {
  const totalSec = Math.max(0, Math.floor(ms / 1000));
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}
function formatClock(date, lang) {
  return date.toLocaleTimeString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { hour: "2-digit", minute: "2-digit" });
}

// Les outils qui gardent des données dans le navigateur (localStorage) plutôt que dans Supabase
// (questions au médecin, plan de naissance, album bedaine, etc.) doivent inclure l'identifiant du
// compte connecté dans la clé — sinon, sur le même appareil/navigateur, un nouveau compte verrait
// les données laissées par un compte précédent. "guest" est utilisé quand personne n'est connecté.
function mmbScopedKey(base, session) {
  const uid = session?.user?.id || "guest";
  return `${base}__u${uid}`;
}

/* ---------------- REGROUPEMENT GÉNÉRIQUE PAR DATE (jour → mois → année) ----------------
   Utilisé partout où on affiche une liste d'éléments datés (trackers, cycle, journal,
   documents, rendez-vous) pour éviter d'avoir une liste interminable au fil des mois/années :
   - Le mois en cours reste affiché à plat, par jour (comme avant).
   - Un mois déjà passé (mais dans l'année en cours) se replie sous un en-tête de mois — on clique
     dessus pour voir ses dates, puis sur une date pour voir ses éléments.
   - Une année déjà passée se replie sous un en-tête d'année — on clique dessus pour voir ses mois,
     puis un mois pour voir ses dates, puis une date pour voir ses éléments.
   Tout est replié par défaut; seul l'ajout d'un nouvel élément pendant l'utilisation en cours
   ouvre automatiquement la chaîne (année/mois/date) qui le contient, pour qu'on le voie tout de
   suite sans avoir à cliquer. */
function DateGroupedList({ items, getDate, getId, renderItem, renderDateAdd, emptyLabel, countLabel, loaded = true, lang }) {
  const dateKey = (d) => d.toISOString().slice(0, 10);
  const monthKey = (d) => d.toISOString().slice(0, 7); // "AAAA-MM"
  const yearKey = (d) => String(d.getFullYear());
  const now = new Date();
  const currentMonthKey = monthKey(now);
  const currentYearKey = yearKey(now);

  const [openDates, setOpenDates] = useState(() => new Set());
  const [openMonths, setOpenMonths] = useState(() => new Set());
  const [openYears, setOpenYears] = useState(() => new Set());
  const toggleIn = (setFn) => (key) => setFn((s) => {
    const next = new Set(s);
    if (next.has(key)) next.delete(key); else next.add(key);
    return next;
  });
  const toggleDate = toggleIn(setOpenDates);
  const toggleMonth = toggleIn(setOpenMonths);
  const toggleYear = toggleIn(setOpenYears);

  // Ouvre automatiquement la date (et son mois/année s'ils sont repliés) d'un élément qui vient
  // d'être ajouté pendant cette utilisation de l'outil — jamais au chargement initial de
  // l'historique. Comme ce chargement (Supabase) est asynchrone, la liste démarre toujours vide
  // puis se remplit un instant après le montage : on attend que `loaded` devienne vrai avant de
  // commencer à comparer, sinon ce remplissage serait pris à tort pour un ajout en direct.
  const prevItemsRef = useRef(null);
  const baselineSetRef = useRef(false);
  useEffect(() => {
    if (!loaded) return;
    if (!baselineSetRef.current) {
      baselineSetRef.current = true;
      prevItemsRef.current = items;
      return;
    }
    const prev = prevItemsRef.current;
    if (items.length > prev.length) {
      const prevIds = new Set(prev.map((it) => getId(it)));
      const added = items.filter((it) => !prevIds.has(getId(it)));
      if (added.length > 0) {
        setOpenDates((s) => { const next = new Set(s); added.forEach((it) => next.add(dateKey(getDate(it)))); return next; });
        setOpenMonths((s) => { const next = new Set(s); added.forEach((it) => next.add(monthKey(getDate(it)))); return next; });
        setOpenYears((s) => { const next = new Set(s); added.forEach((it) => next.add(yearKey(getDate(it)))); return next; });
      }
    }
    prevItemsRef.current = items;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, loaded]);

  if (items.length === 0) return (
    <div style={{
      textAlign: "center", padding: "16px 12px", marginTop: 14, borderRadius: 12,
      border: `1px dashed ${COLORS.line}`, background: COLORS.cream,
    }}>
      <p style={{ fontSize: 12.5, color: COLORS.muted, fontStyle: "italic", margin: 0 }}>{emptyLabel}</p>
    </div>
  );

  const todayLabel = lang === "fr" ? "Aujourd'hui" : lang === "es" ? "Hoy" : "Today";
  const yesterdayLabel = lang === "fr" ? "Hier" : lang === "es" ? "Ayer" : "Yesterday";
  const locale = lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA";
  const todayKeyStr = dateKey(now);
  const yesterdayKeyStr = dateKey(new Date(Date.now() - 86400000));
  const dateHeading = (d) => {
    const key = dateKey(d);
    if (key === todayKeyStr) return todayLabel;
    if (key === yesterdayKeyStr) return yesterdayLabel;
    return d.toLocaleDateString(locale, { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  };
  const monthHeading = (d) => d.toLocaleDateString(locale, { month: "long", year: "numeric" });

  const headerRowStyle = {
    width: "100%", display: "flex", justifyContent: "space-between", alignItems: "center",
    background: "none", border: "none", cursor: "pointer", padding: "6px 2px",
    borderBottom: `1px solid ${COLORS.line}`, textAlign: "left",
  };
  const chevron = (isOpen) => (
    <ChevronRight size={15} style={{ transform: isOpen ? "rotate(90deg)" : "rotate(0deg)", transition: "transform 0.15s" }} />
  );

  // Regroupe d'abord par jour civil, du plus récent au plus ancien.
  const sorted = items.slice().sort((a, b) => (getDate(b) || 0) - (getDate(a) || 0));
  const dateGroups = [];
  for (const it of sorted) {
    const d = getDate(it) || new Date();
    const key = dateKey(d);
    let g = dateGroups.find((g) => g.key === key);
    if (!g) g = { key, date: d, items: [] }, dateGroups.push(g);
    g.items.push(it);
  }

  const renderDateGroup = (g) => {
    const isOpen = openDates.has(g.key);
    return (
      <div key={g.key} style={{ marginBottom: 8 }}>
        <button onClick={() => toggleDate(g.key)} style={headerRowStyle}>
          <span style={{ fontSize: 12.5, fontWeight: 800, color: COLORS.text, textTransform: "uppercase", letterSpacing: 0.3 }}>
            {dateHeading(g.date)}
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 6, color: COLORS.muted, fontSize: 12 }}>
            {countLabel(g.items.length)}
            {chevron(isOpen)}
          </span>
        </button>
        {isOpen && (
          <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 8 }}>
            {g.items.map((it) => renderItem(it))}
            {/* L'ajout rétroactif ne s'affiche que pour les jours passés — pour aujourd'hui, le
                formulaire principal en haut de l'outil sert déjà à ça, et l'afficher deux fois
                (une fois en haut, une fois ici) créait un doublon visuel confus. */}
            {renderDateAdd && g.key !== todayKeyStr && renderDateAdd(g.date)}
          </div>
        )}
      </div>
    );
  };

  // Sépare : mois en cours (affiché à plat par date) / mois passés de l'année en cours (repliés par
  // mois) / années passées (repliées par année, puis par mois à l'intérieur).
  const currentMonthGroups = [];
  const monthBuckets = new Map(); // monthKey -> { date, groups: [dateGroup] } — pour les mois passés de l'année en cours
  const yearBuckets = new Map();  // yearKey -> Map(monthKey -> { date, groups }) — pour les années passées

  for (const g of dateGroups) {
    const mKey = monthKey(g.date);
    const yKey = yearKey(g.date);
    if (mKey === currentMonthKey) {
      currentMonthGroups.push(g);
    } else if (yKey === currentYearKey) {
      if (!monthBuckets.has(mKey)) monthBuckets.set(mKey, { date: g.date, groups: [] });
      monthBuckets.get(mKey).groups.push(g);
    } else {
      if (!yearBuckets.has(yKey)) yearBuckets.set(yKey, new Map());
      const yearMonths = yearBuckets.get(yKey);
      if (!yearMonths.has(mKey)) yearMonths.set(mKey, { date: g.date, groups: [] });
      yearMonths.get(mKey).groups.push(g);
    }
  }

  const renderMonthBucket = (mKey, bucket) => {
    const isOpen = openMonths.has(mKey);
    const total = bucket.groups.reduce((n, g) => n + g.items.length, 0);
    return (
      <div key={mKey} style={{ marginBottom: 8 }}>
        <button onClick={() => toggleMonth(mKey)} style={headerRowStyle}>
          <span style={{ fontSize: 12.5, fontWeight: 800, color: COLORS.text, textTransform: "capitalize", letterSpacing: 0.3 }}>
            {monthHeading(bucket.date)}
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 6, color: COLORS.muted, fontSize: 12 }}>
            {countLabel(total)}
            {chevron(isOpen)}
          </span>
        </button>
        {isOpen && (
          <div style={{ marginTop: 8, paddingLeft: 10 }}>
            {bucket.groups.map((g) => renderDateGroup(g))}
          </div>
        )}
      </div>
    );
  };

  const renderYearBucket = (yKey, yearMonths) => {
    const isOpen = openYears.has(yKey);
    const monthEntries = Array.from(yearMonths.entries()).sort((a, b) => b[0].localeCompare(a[0]));
    const total = monthEntries.reduce((n, [, bucket]) => n + bucket.groups.reduce((m, g) => m + g.items.length, 0), 0);
    return (
      <div key={yKey} style={{ marginBottom: 8 }}>
        <button onClick={() => toggleYear(yKey)} style={headerRowStyle}>
          <span style={{ fontSize: 13, fontWeight: 800, color: COLORS.text, letterSpacing: 0.3 }}>{yKey}</span>
          <span style={{ display: "flex", alignItems: "center", gap: 6, color: COLORS.muted, fontSize: 12 }}>
            {countLabel(total)}
            {chevron(isOpen)}
          </span>
        </button>
        {isOpen && (
          <div style={{ marginTop: 8, paddingLeft: 10 }}>
            {monthEntries.map(([mKey, bucket]) => renderMonthBucket(mKey, bucket))}
          </div>
        )}
      </div>
    );
  };

  const sortedMonthKeys = Array.from(monthBuckets.keys()).sort((a, b) => b.localeCompare(a));
  const sortedYearKeys = Array.from(yearBuckets.keys()).sort((a, b) => b.localeCompare(a));

  return (
    <div style={{ marginTop: 14 }}>
      {currentMonthGroups.map((g) => renderDateGroup(g))}
      {sortedMonthKeys.map((mKey) => renderMonthBucket(mKey, monthBuckets.get(mKey)))}
      {sortedYearKeys.map((yKey) => renderYearBucket(yKey, yearBuckets.get(yKey)))}
    </div>
  );
}

function TrackerLogList({ entries, emptyLabel, onDelete, renderDateAdd, loaded, lang }) {
  const entryWord = lang === "fr" ? "entrée" : lang === "es" ? "entrada" : "entry";
  const entriesWord = lang === "fr" ? "entrées" : lang === "es" ? "entradas" : "entries";
  return (
    <DateGroupedList
      items={entries}
      getDate={(e) => e.createdAt || new Date()}
      getId={(e) => e.id}
      emptyLabel={emptyLabel}
      countLabel={(n) => `${n} ${n > 1 ? entriesWord : entryWord}`}
      loaded={loaded}
      lang={lang}
      renderDateAdd={renderDateAdd}
      renderItem={(e) => (
        <div key={e.id} style={{
          display: "flex", justifyContent: "space-between", alignItems: "center",
          background: COLORS.cream, borderRadius: 10, padding: "9px 13px", fontSize: 13, gap: 8,
        }}>
          <span style={{ color: COLORS.text, fontWeight: 600 }}>{e.label}</span>
          <span style={{ color: COLORS.muted, flex: 1, textAlign: "right" }}>{e.detail}</span>
          {onDelete && (
            <button
              onClick={() => onDelete(e.id)}
              aria-label={lang === "fr" ? "Supprimer" : lang === "es" ? "Eliminar" : "Delete"}
              style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.muted, padding: 2, display: "flex", flexShrink: 0 }}
            >
              <X size={15} />
            </button>
          )}
        </div>
      )}
    />
  );
}

function FeedingTracker({ lang, session }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [trackSession, setTrackSession] = useState(null); // { side, start }
  const [log, setLog] = useState([]);
  const hasSession = !!(session?.access_token && session?.user?.id);
  const M = lang === "fr"
    ? {
        left: "Sein gauche", right: "Sein droit", bottle: "Biberon", pump: "Tire-lait", stop: "Arrêter", inProgress: "En cours",
        qtyPh: "Quantité", ml: "ml", oz: "oz", save: "Enregistrer", cancel: "Annuler",
        todayTotal: (v, u) => `Aujourd'hui : ${v} ${u} au total (biberon + tire-lait)`,
      }
    : lang === "es"
    ? {
        left: "Seno izquierdo", right: "Seno derecho", bottle: "Biberón", pump: "Extractor de leche", stop: "Detener", inProgress: "En curso",
        qtyPh: "Cantidad", ml: "ml", oz: "oz", save: "Guardar", cancel: "Cancelar",
        todayTotal: (v, u) => `Hoy: ${v} ${u} en total (biberón + extractor)`,
      }
    : {
        left: "Left breast", right: "Right breast", bottle: "Bottle", pump: "Pumping", stop: "Stop", inProgress: "In progress",
        qtyPh: "Quantity", ml: "ml", oz: "oz", save: "Save", cancel: "Cancel",
        todayTotal: (v, u) => `Today: ${v} ${u} total (bottle + pumping)`,
      };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "feeding", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const persist = (type, entry, tempId) => persistTrackerEntry(type, entry, session, setLog, tempId);

  const start = (side) => setTrackSession({ side, start: new Date() });
  const stop = () => {
    if (!trackSession) return;
    const durationMs = new Date() - trackSession.start;
    const entry = { label: trackSession.side, detail: `${formatClock(trackSession.start, lang)} · ${formatDuration(durationMs, lang)}` };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
    setTrackSession(null);
  };
  // Quantité (ml/oz) au biberon et au tire-lait — encodée directement dans le texte du "detail"
  // (ex. "14:32 · 120 ml"), comme le poids de grossesse, plutôt que d'ajouter une colonne structurée
  // dans la table générique tracker_entries. Un total du jour est calculé en reparsant ce texte.
  const [qtyUnit, setQtyUnit] = useState(lang === "en" ? "oz" : "ml");
  const mlPerOz = 29.5735;
  const [bottlePending, setBottlePending] = useState(false);
  const [bottleQty, setBottleQty] = useState("");
  const logBottle = () => {
    const qty = Number(bottleQty);
    const detail = qty > 0 ? `${formatClock(new Date(), lang)} · ${qty} ${qtyUnit}` : formatClock(new Date(), lang);
    const entry = { label: M.bottle, detail };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
    setBottlePending(false);
    setBottleQty("");
  };
  const [pumpPending, setPumpPending] = useState(false);
  const [pumpQty, setPumpQty] = useState("");
  const logPump = () => {
    const qty = Number(pumpQty);
    const detail = qty > 0 ? `${formatClock(new Date(), lang)} · ${qty} ${qtyUnit}` : formatClock(new Date(), lang);
    const entry = { label: M.pump, detail };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
    setPumpPending(false);
    setPumpQty("");
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);

  // Total du jour, tous les biberons + séances de tire-lait confondus (converti dans l'unité choisie).
  const todayKey = new Date().toDateString();
  const parseQtyMl = (detail) => {
    const m = detail && detail.match(/([\d.]+)\s?(ml|oz)/i);
    if (!m) return 0;
    const val = parseFloat(m[1]);
    return /oz/i.test(m[2]) ? val * mlPerOz : val;
  };
  const todayTotalMl = log
    .filter((e) => (e.label === M.bottle || e.label === M.pump) && (e.start || e.createdAt) && (e.start || e.createdAt).toDateString() === todayKey)
    .reduce((sum, e) => sum + parseQtyMl(e.detail), 0);
  const todayTotalDisplay = qtyUnit === "ml" ? Math.round(todayTotalMl) : Math.round((todayTotalMl / mlPerOz) * 10) / 10;
  const saveWord = lang === "fr" ? "Sauvegarder" : lang === "es" ? "Guardar" : "Save";
  // Ajout rétroactif pour une date passée — seul le biberon est proposé ici via ce mécanisme (l'ajout
  // manuel avec heures de début/fin, juste en dessous, couvre maintenant l'allaitement au sein pour
  // les personnes qui préfèrent noter après coup plutôt que garder un chrono en direct).
  const addBottleForDate = (date) => {
    const entry = { label: M.bottle, detail: formatClock(date, lang), createdAt: date };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
  };
  const renderDateAdd = (date) => (
    <button onClick={() => addBottleForDate(date)} style={{
      marginTop: 8, width: "100%", padding: "9px", borderRadius: 10, border: `1px dashed ${COLORS.line}`,
      background: "#fff", color: COLORS.pink, fontWeight: 700, fontSize: 12.5, cursor: "pointer",
    }}>+ {M.bottle}</button>
  );

  // Ajout manuel d'une tétée (début → fin) sans chronomètre en direct — pour les personnes qui
  // préfèrent noter à la fin de la journée plutôt que de garder l'appli ouverte pendant la tétée.
  const ME = lang === "fr"
    ? { manualToggle: "Entrer une tétée manuellement", startLabel: "Début", endLabel: "Fin", add: "Ajouter", cancel: "Annuler" }
    : lang === "es"
    ? { manualToggle: "Ingresar una toma manualmente", startLabel: "Inicio", endLabel: "Fin", add: "Agregar", cancel: "Cancelar" }
    : { manualToggle: "Enter a feeding manually", startLabel: "Start", endLabel: "End", add: "Add", cancel: "Cancel" };
  const [manualOpen, setManualOpen] = useState(false);
  const [manualSide, setManualSide] = useState(M.left);
  const [manualStart, setManualStart] = useState("");
  const [manualEnd, setManualEnd] = useState("");
  useEffect(() => { setManualSide(M.left); }, [lang]); // suit la langue si elle change pendant que le formulaire est ouvert
  const timeStrToDate = (timeStr) => {
    const [h, m] = timeStr.split(":").map(Number);
    const d = new Date();
    d.setHours(h, m, 0, 0);
    return d;
  };
  const addManualFeed = () => {
    if (!manualStart || !manualEnd) return;
    const start = timeStrToDate(manualStart);
    let end = timeStrToDate(manualEnd);
    if (end <= start) end = new Date(end.getTime() + 24 * 60 * 60 * 1000); // plage qui traverse minuit
    const entry = { label: manualSide, detail: `${formatClock(start, lang)} · ${formatDuration(end - start, lang)}`, createdAt: start };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
    setManualStart("");
    setManualEnd("");
  };

  return (
    <Card>
      <div style={{ background: "#FDF0F3", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <FeedingHeroIllu size={130} />
      </div>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 4 }}>
        {[M.left, M.right].map((side) => (
          <button key={side} onClick={() => (trackSession?.side === side ? stop() : start(side))} style={{
            flex: 1, minWidth: 130, padding: "14px 10px", borderRadius: 14, border: "none", cursor: "pointer",
            background: trackSession?.side === side ? COLORS.pink : "#FDF0F3", color: trackSession?.side === side ? "#fff" : COLORS.pink,
            fontWeight: 700, fontSize: 14,
          }}>
            {side}{trackSession?.side === side ? ` · ${formatDuration(new Date() - trackSession.start, lang)} — ${saveWord}` : ""}
          </button>
        ))}
      </div>
      {todayTotalMl > 0 && (
        <p style={{ margin: "10px 0 0", fontSize: 12, fontWeight: 700, color: COLORS.pink, background: "#FDF0F3", borderRadius: 10, padding: "8px 12px", textAlign: "center" }}>
          {M.todayTotal(todayTotalDisplay, qtyUnit)}
        </p>
      )}

      <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
        <button onClick={() => { setBottlePending((v) => !v); setPumpPending(false); }} style={{
          flex: 1, padding: "12px", borderRadius: 12, cursor: "pointer",
          border: `2px solid ${bottlePending ? COLORS.pink : COLORS.line}`, background: "#fff",
          color: COLORS.teal, fontWeight: 700, fontSize: 13.5,
        }}>+ {M.bottle}</button>
        <button onClick={() => { setPumpPending((v) => !v); setBottlePending(false); }} style={{
          flex: 1, padding: "12px", borderRadius: 12, cursor: "pointer",
          border: `2px solid ${pumpPending ? COLORS.pink : COLORS.line}`, background: "#fff",
          color: COLORS.teal, fontWeight: 700, fontSize: 13.5,
        }}>+ {M.pump}</button>
      </div>

      {(bottlePending || pumpPending) && (
        <div style={{ marginTop: 8, background: "#FDF0F3", borderRadius: 12, padding: 12 }}>
          <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
            <input
              type="number" step="1" min="0" placeholder={M.qtyPh}
              value={bottlePending ? bottleQty : pumpQty}
              onChange={(e) => (bottlePending ? setBottleQty(e.target.value) : setPumpQty(e.target.value))}
              style={{ flex: 1, padding: "9px 11px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14, boxSizing: "border-box" }}
            />
            <div style={{ display: "flex", gap: 4 }}>
              {["ml", "oz"].map((u) => (
                <button key={u} onClick={() => setQtyUnit(u)} style={{
                  padding: "9px 12px", borderRadius: 10, fontSize: 12.5, fontWeight: 700, cursor: "pointer",
                  border: `1px solid ${qtyUnit === u ? COLORS.pink : COLORS.line}`,
                  background: qtyUnit === u ? COLORS.pink : "#fff", color: qtyUnit === u ? "#fff" : COLORS.muted,
                }}>{u === "ml" ? M.ml : M.oz}</button>
              ))}
            </div>
          </div>
          <button onClick={bottlePending ? logBottle : logPump} style={{
            width: "100%", padding: "12px", borderRadius: 12, border: "none", background: COLORS.pink, color: "#fff",
            fontWeight: 800, fontSize: 13.5, cursor: "pointer",
          }}>{saveWord}</button>
        </div>
      )}
      {!trackSession && (
        <div style={{ marginTop: 10 }}>
          <button onClick={() => setManualOpen((v) => !v)} style={{
            background: "none", border: "none", color: COLORS.pink, fontSize: 12.5, fontWeight: 700,
            textDecoration: "underline", cursor: "pointer", padding: "4px 0",
          }}>{manualOpen ? ME.cancel : ME.manualToggle}</button>
          {manualOpen && (
            <div style={{ marginTop: 8, background: "#FDF0F3", borderRadius: 12, padding: 12 }}>
              <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                {[M.left, M.right].map((side) => (
                  <button key={side} onClick={() => setManualSide(side)} style={{
                    flex: 1, padding: "9px 6px", borderRadius: 10, cursor: "pointer",
                    border: `2px solid ${manualSide === side ? COLORS.pink : "transparent"}`,
                    background: "#fff", color: COLORS.pink, fontWeight: 700, fontSize: 12.5,
                  }}>{side}</button>
                ))}
              </div>
              <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                <label style={{ flex: 1, fontSize: 11.5, color: COLORS.muted, fontWeight: 700 }}>
                  {ME.startLabel}
                  <input type="time" value={manualStart} onChange={(e) => setManualStart(e.target.value)} style={{
                    display: "block", width: "100%", marginTop: 4, padding: "8px 10px", borderRadius: 8,
                    border: `1px solid ${COLORS.line}`, fontSize: 14, boxSizing: "border-box",
                  }} />
                </label>
                <label style={{ flex: 1, fontSize: 11.5, color: COLORS.muted, fontWeight: 700 }}>
                  {ME.endLabel}
                  <input type="time" value={manualEnd} onChange={(e) => setManualEnd(e.target.value)} style={{
                    display: "block", width: "100%", marginTop: 4, padding: "8px 10px", borderRadius: 8,
                    border: `1px solid ${COLORS.line}`, fontSize: 14, boxSizing: "border-box",
                  }} />
                </label>
              </div>
              <button onClick={addManualFeed} disabled={!manualStart || !manualEnd} style={{
                width: "100%", padding: "10px", borderRadius: 10, border: "none",
                cursor: manualStart && manualEnd ? "pointer" : "default",
                background: manualStart && manualEnd ? COLORS.pink : COLORS.line, color: "#fff",
                fontWeight: 800, fontSize: 13, opacity: manualStart && manualEnd ? 1 : 0.6,
              }}>{ME.add}</button>
            </div>
          )}
        </div>
      )}
      <TrackerLogList entries={log} emptyLabel={emptyLabel} onDelete={removeEntry} renderDateAdd={renderDateAdd} loaded={loaded} lang={lang} />
    </Card>
  );
}

function SleepTracker({ lang, session }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [trackSession, setTrackSession] = useState(null);
  const [log, setLog] = useState([]);
  const hasSession = !!(session?.access_token && session?.user?.id);
  const M = lang === "fr" ? { start: "Bébé s'endort", stop: "Bébé se réveille" } : lang === "es" ? { start: "El bebé se duerme", stop: "El bebé se despierta" } : { start: "Baby falls asleep", stop: "Baby wakes up" };
  // Pour les personnes qui préfèrent noter les périodes de sommeil après coup plutôt que de garder
  // l'appli ouverte avec un chronomètre en direct (ex. en fin de journée, plusieurs siestes d'un coup).
  const ME = lang === "fr"
    ? { manualToggle: "Entrer une plage manuellement", startLabel: "Début", endLabel: "Fin", add: "Ajouter", cancel: "Annuler" }
    : lang === "es"
    ? { manualToggle: "Ingresar un rango manualmente", startLabel: "Inicio", endLabel: "Fin", add: "Agregar", cancel: "Cancelar" }
    : { manualToggle: "Enter a time range manually", startLabel: "Start", endLabel: "End", add: "Add", cancel: "Cancel" };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "sleep", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const toggle = () => {
    if (trackSession) {
      const durationMs = new Date() - trackSession.start;
      const entry = { label: formatClock(trackSession.start, lang), detail: formatDuration(durationMs, lang) };
      const optimistic = makeOptimisticEntry(entry);
      setLog((l) => [...l, optimistic]);
      persistTrackerEntry("sleep", entry, session, setLog, optimistic.id);
      setTrackSession(null);
    } else {
      setTrackSession({ start: new Date() });
    }
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);

  // Ajout manuel d'une plage (début → fin), sans chronomètre en direct.
  const [manualOpen, setManualOpen] = useState(false);
  const [manualStart, setManualStart] = useState("");
  const [manualEnd, setManualEnd] = useState("");
  const timeStrToDate = (timeStr) => {
    const [h, m] = timeStr.split(":").map(Number);
    const d = new Date();
    d.setHours(h, m, 0, 0);
    return d;
  };
  const addManual = () => {
    if (!manualStart || !manualEnd) return;
    const start = timeStrToDate(manualStart);
    let end = timeStrToDate(manualEnd);
    if (end <= start) end = new Date(end.getTime() + 24 * 60 * 60 * 1000); // plage qui traverse minuit
    const entry = { label: formatClock(start, lang), detail: formatDuration(end - start, lang), createdAt: start };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persistTrackerEntry("sleep", entry, session, setLog, optimistic.id);
    setManualStart("");
    setManualEnd("");
  };

  return (
    <Card>
      <div style={{ background: "#EAF2F8", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <SleepHeroIllu size={130} />
      </div>
      <button onClick={toggle} style={{
        width: "100%", padding: "18px", borderRadius: 16, border: "none", cursor: "pointer",
        background: trackSession ? COLORS.blue : "#EAF2F8", color: trackSession ? "#fff" : COLORS.blue,
        fontWeight: 800, fontSize: 15,
      }}>
        {trackSession ? `${lang === "fr" ? "Sauvegarder" : lang === "es" ? "Guardar" : "Save"} · ${formatDuration(new Date() - trackSession.start, lang)}` : M.start}
      </button>
      {!trackSession && (
        <div style={{ marginTop: 10 }}>
          <button onClick={() => setManualOpen((v) => !v)} style={{
            background: "none", border: "none", color: COLORS.blue, fontSize: 12.5, fontWeight: 700,
            textDecoration: "underline", cursor: "pointer", padding: "4px 0",
          }}>{manualOpen ? ME.cancel : ME.manualToggle}</button>
          {manualOpen && (
            <div style={{ marginTop: 8, background: "#EAF2F8", borderRadius: 12, padding: 12 }}>
              <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                <label style={{ flex: 1, fontSize: 11.5, color: COLORS.muted, fontWeight: 700 }}>
                  {ME.startLabel}
                  <input type="time" value={manualStart} onChange={(e) => setManualStart(e.target.value)} style={{
                    display: "block", width: "100%", marginTop: 4, padding: "8px 10px", borderRadius: 8,
                    border: `1px solid ${COLORS.line}`, fontSize: 14, boxSizing: "border-box",
                  }} />
                </label>
                <label style={{ flex: 1, fontSize: 11.5, color: COLORS.muted, fontWeight: 700 }}>
                  {ME.endLabel}
                  <input type="time" value={manualEnd} onChange={(e) => setManualEnd(e.target.value)} style={{
                    display: "block", width: "100%", marginTop: 4, padding: "8px 10px", borderRadius: 8,
                    border: `1px solid ${COLORS.line}`, fontSize: 14, boxSizing: "border-box",
                  }} />
                </label>
              </div>
              <button onClick={addManual} disabled={!manualStart || !manualEnd} style={{
                width: "100%", padding: "10px", borderRadius: 10, border: "none",
                cursor: manualStart && manualEnd ? "pointer" : "default",
                background: manualStart && manualEnd ? COLORS.blue : COLORS.line, color: "#fff",
                fontWeight: 800, fontSize: 13, opacity: manualStart && manualEnd ? 1 : 0.6,
              }}>{ME.add}</button>
            </div>
          )}
        </div>
      )}
      <TrackerLogList entries={log} emptyLabel={emptyLabel} onDelete={removeEntry} loaded={loaded} lang={lang} />
    </Card>
  );
}

function DiaperTracker({ lang, session }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [log, setLog] = useState([]);
  const hasSession = !!(session?.access_token && session?.user?.id);
  const M = lang === "fr" ? { pee: "Pipi", poop: "Selle", both: "Les deux" } : lang === "es" ? { pee: "Pipí", poop: "Popó", both: "Ambos" } : { pee: "Wet", poop: "Dirty", both: "Both" };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "diaper", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const [selectedType, setSelectedType] = useState(null);
  const saveLabel = lang === "fr" ? "Sauvegarder" : lang === "es" ? "Guardar" : "Save";
  const add = () => {
    if (!selectedType) return;
    const entry = { label: selectedType, detail: formatClock(new Date(), lang) };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persistTrackerEntry("diaper", entry, session, setLog, optimistic.id);
    setSelectedType(null);
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);
  // Ajout rétroactif pour une date passée (ex. « j'ai oublié d'entrer une couche d'hier ») —
  // toujours via les mêmes boutons de type, jamais de texte à écrire.
  const dateKeyOf = (d) => d.toISOString().slice(0, 10);
  const [addTypeByDate, setAddTypeByDate] = useState({}); // { [dateKey]: type }
  const addForDate = (date) => {
    const key = dateKeyOf(date);
    const type = addTypeByDate[key];
    if (!type) return;
    const entry = { label: type, detail: formatClock(date, lang), createdAt: date };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persistTrackerEntry("diaper", entry, session, setLog, optimistic.id);
    setAddTypeByDate((prev) => { const next = { ...prev }; delete next[key]; return next; });
  };
  const renderDateAdd = (date) => {
    const key = dateKeyOf(date);
    const selected = addTypeByDate[key];
    return (
      <div style={{ marginTop: 8 }}>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 6 }}>
          {[M.pee, M.poop, M.both].map((type) => (
            <button key={type} onClick={() => setAddTypeByDate((prev) => ({ ...prev, [key]: type }))} style={{
              flex: 1, minWidth: 80, padding: "9px 6px", borderRadius: 10, cursor: "pointer",
              border: `2px solid ${selected === type ? COLORS.sage : "transparent"}`,
              background: "#F0F5EC", color: COLORS.sage, fontWeight: 700, fontSize: 12,
            }}>{type}</button>
          ))}
        </div>
        <button onClick={() => addForDate(date)} disabled={!selected} style={{
          width: "100%", padding: "9px", borderRadius: 10, border: "none", cursor: selected ? "pointer" : "default",
          background: selected ? COLORS.sage : COLORS.line, color: "#fff", fontWeight: 800, fontSize: 12.5,
          opacity: selected ? 1 : 0.6,
        }}>{saveLabel}</button>
      </div>
    );
  };

  return (
    <Card>
      <div style={{ background: "#F0F5EC", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <DiaperHeroIllu size={130} />
      </div>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 12 }}>
        {[M.pee, M.poop, M.both].map((type) => (
          <button key={type} onClick={() => setSelectedType(type)} style={{
            flex: 1, minWidth: 100, padding: "16px 10px", borderRadius: 14, cursor: "pointer",
            border: `2px solid ${selectedType === type ? COLORS.sage : "transparent"}`,
            background: "#F0F5EC", color: COLORS.sage, fontWeight: 700, fontSize: 14,
          }}>{type}</button>
        ))}
      </div>
      <button onClick={add} disabled={!selectedType} style={{
        width: "100%", padding: "14px", borderRadius: 14, border: "none", cursor: selectedType ? "pointer" : "default",
        background: selectedType ? COLORS.sage : COLORS.line, color: "#fff", fontWeight: 800, fontSize: 14.5,
        opacity: selectedType ? 1 : 0.6,
      }}>{saveLabel}</button>
      <TrackerLogList entries={log} emptyLabel={emptyLabel} onDelete={removeEntry} renderDateAdd={renderDateAdd} loaded={loaded} lang={lang} />
    </Card>
  );
}

function KickTracker({ lang, session }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [count, setCount] = useState(0);
  const [sessionStart, setSessionStart] = useState(null);
  const [log, setLog] = useState([]);
  const hasSession = !!(session?.access_token && session?.user?.id);
  const M = lang === "fr"
    ? { title: "Compte-coups de bébé", subtitle: "Chaque fois que vous sentez bébé bouger ou donner un coup, touchez le bouton — ça compte les mouvements pour surveiller sa forme.", add: "+1 coup", reset: "Sauvegarder", tip: "Le repère habituel est d'environ 10 coups en moins de 2 heures. Si vous en sentez beaucoup moins que d'habitude, contactez votre professionnel de la santé." }
    : lang === "es"
    ? { title: "Contador de movimientos del bebé", subtitle: "Cada vez que sientas al bebé moverse o dar una patada, toca el botón — esto cuenta los movimientos para vigilar su bienestar.", add: "+1 movimiento", reset: "Guardar", tip: "La referencia habitual es de unos 10 movimientos en menos de 2 horas. Si sientes muchos menos de lo habitual, contacta a tu profesional de la salud." }
    : { title: "Baby kick counter", subtitle: "Every time you feel baby move or kick, tap the button — this counts baby's movements to help monitor their wellbeing.", add: "+1 kick", reset: "Save", tip: "A common guideline is about 10 kicks in under 2 hours. If you notice far fewer than usual, contact your healthcare provider." };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "kick", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const add = () => { if (!sessionStart) setSessionStart(new Date()); setCount((c) => c + 1); };
  const reset = () => {
    if (sessionStart) {
      const entry = { label: `${count} ${lang === "fr" ? "coups" : lang === "es" ? "movimientos" : "kicks"}`, detail: `${formatClock(sessionStart, lang)} → ${formatClock(new Date(), lang)}` };
      const optimistic = makeOptimisticEntry(entry);
      setLog((l) => [...l, optimistic]);
      persistTrackerEntry("kick", entry, session, setLog, optimistic.id);
    }
    setCount(0); setSessionStart(null);
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);
  // Ajout rétroactif pour une date passée (ex. « j'ai oublié d'entrer un coup d'hier ») — même
  // bouton « +1 coup », juste appliqué à la date choisie au lieu de maintenant.
  const dateKeyOf = (d) => d.toISOString().slice(0, 10);
  const [countByDate, setCountByDate] = useState({}); // { [dateKey]: count }
  const addForDate = (date) => {
    const key = dateKeyOf(date);
    const c = countByDate[key] || 0;
    if (c <= 0) return;
    const entry = { label: `${c} ${lang === "fr" ? "coups" : lang === "es" ? "movimientos" : "kicks"}`, detail: formatClock(date, lang), createdAt: date };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persistTrackerEntry("kick", entry, session, setLog, optimistic.id);
    setCountByDate((prev) => { const next = { ...prev }; delete next[key]; return next; });
  };
  const renderDateAdd = (date) => {
    const key = dateKeyOf(date);
    const c = countByDate[key] || 0;
    return (
      <div style={{ marginTop: 8, display: "flex", gap: 8 }}>
        <button onClick={() => setCountByDate((prev) => ({ ...prev, [key]: (prev[key] || 0) + 1 }))} style={{
          flex: 1, padding: "9px", borderRadius: 10, border: "none", background: COLORS.ochre, color: "#fff",
          fontWeight: 800, fontSize: 12.5, cursor: "pointer",
        }}>{M.add}{c > 0 ? ` (${c})` : ""}</button>
        <button onClick={() => addForDate(date)} disabled={c === 0} style={{
          padding: "9px 14px", borderRadius: 10, border: `1px solid ${COLORS.line}`, background: "#fff",
          color: COLORS.muted, fontWeight: 700, fontSize: 12, cursor: c > 0 ? "pointer" : "default", opacity: c > 0 ? 1 : 0.5,
        }}>{M.reset}</button>
      </div>
    );
  };

  return (
    <Card>
      <div style={{ background: "#FBF3E4", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <KickHeroIllu size={130} />
      </div>
      <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 17, color: COLORS.teal }}>{M.title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 12.5, color: COLORS.muted, lineHeight: 1.5 }}>{M.subtitle}</p>
      <div style={{ textAlign: "center", marginBottom: 14 }}>
        <div style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 48, color: COLORS.ochre, fontWeight: 700 }}>{count}</div>
        {sessionStart && <div style={{ fontSize: 12.5, color: COLORS.muted }}>{lang === "fr" ? "Depuis" : lang === "es" ? "Desde" : "Since"} {formatClock(sessionStart, lang)}</div>}
      </div>
      <div style={{ display: "flex", gap: 10 }}>
        <button onClick={add} style={{ flex: 1, padding: "16px", borderRadius: 14, border: "none", background: COLORS.ochre, color: "#fff", fontWeight: 800, fontSize: 15, cursor: "pointer" }}>{M.add}</button>
        <button onClick={reset} disabled={!sessionStart} style={{ padding: "16px 18px", borderRadius: 14, border: `1px solid ${COLORS.line}`, background: "#fff", color: COLORS.muted, fontWeight: 700, fontSize: 13, cursor: sessionStart ? "pointer" : "default", opacity: sessionStart ? 1 : 0.5 }}>{M.reset}</button>
      </div>
      <p style={{ fontSize: 12, color: COLORS.muted, lineHeight: 1.5, marginTop: 12 }}>{M.tip}</p>
      <TrackerLogList entries={log} emptyLabel={emptyLabel} onDelete={removeEntry} renderDateAdd={renderDateAdd} loaded={loaded} lang={lang} />
    </Card>
  );
}

function ContractionTracker({ lang, session }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [active, setActive] = useState(null);
  const [log, setLog] = useState([]);
  // Historique numérique (durée/intervalle en ms) de la session en cours, utilisé pour détecter
  // le motif "5-1-1" en temps réel — distinct de `log` (texte affiché + Supabase) qui ne garde
  // pas ces valeurs sous forme exploitable.
  const [sessionLog, setSessionLog] = useState([]);
  const hasSession = !!(session?.access_token && session?.user?.id);
  const [tick, setTick] = useState(0); // force le re-rendu chaque seconde pour un minuteur "en direct"
  const [notifStatus, setNotifStatus] = useState(
    typeof Notification !== "undefined" ? Notification.permission : "unsupported"
  );
  const notifiedRef = useRef(false);
  const M = lang === "fr"
    ? { start: "Début de contraction", stop: "Fin de contraction", duration: "Durée", interval: "Depuis la précédente",
        tip: "La règle du 5-1-1 (contractions aux 5 minutes, durant 1 minute, depuis 1 heure) est souvent utilisée comme repère pour se rendre à l'hôpital — validez toujours avec votre professionnel de la santé.",
        save: "Sauvegarder", inProgress: "Contraction en cours",
        alertTitle: "Motif 5-1-1 détecté", alertBody: "Vos dernières contractions suivent le rythme du 5-1-1 (environ aux 5 minutes, d'une durée d'environ 1 minute, depuis environ 1 heure). C'est souvent le moment recommandé de contacter votre professionnel de la santé ou de vous rendre à l'hôpital.",
        enableNotif: "Activer les notifications 5-1-1", notifOn: "Notifications activées ✓", notifBlocked: "Notifications bloquées dans le navigateur",
        notifTitle: "Motif 5-1-1 détecté", notifBody: "Vos contractions suivent le rythme du 5-1-1 — envisagez de contacter votre professionnel de la santé.",
      }
    : lang === "es"
    ? { start: "Inicio de contracción", stop: "Fin de contracción", duration: "Duración", interval: "Desde la anterior",
        tip: "La regla del 5-1-1 (contracciones cada 5 minutos, con duración de 1 minuto, durante 1 hora) se usa a menudo como referencia para ir al hospital — confirma siempre con tu profesional de la salud.",
        save: "Guardar", inProgress: "Contracción en curso",
        alertTitle: "Patrón 5-1-1 detectado", alertBody: "Tus últimas contracciones siguen el ritmo del 5-1-1 (cada 5 minutos aprox., de 1 minuto de duración aprox., desde hace 1 hora aprox.). Suele ser el momento recomendado para contactar a tu profesional de la salud o ir al hospital.",
        enableNotif: "Activar notificaciones 5-1-1", notifOn: "Notificaciones activadas ✓", notifBlocked: "Notificaciones bloqueadas en el navegador",
        notifTitle: "Patrón 5-1-1 detectado", notifBody: "Tus contracciones siguen el ritmo del 5-1-1 — considera contactar a tu profesional de la salud.",
      }
    : { start: "Start contraction", stop: "End contraction", duration: "Duration", interval: "Since previous",
        tip: "The 5-1-1 rule (contractions every 5 minutes, lasting 1 minute, for 1 hour) is often used as a guideline for heading to the hospital — always confirm with your healthcare provider.",
        save: "Save", inProgress: "Contraction in progress",
        alertTitle: "5-1-1 pattern detected", alertBody: "Your recent contractions are following the 5-1-1 rhythm (about every 5 minutes, lasting about 1 minute, for about 1 hour). This is often the recommended time to contact your healthcare provider or head to the hospital.",
        enableNotif: "Turn on 5-1-1 notifications", notifOn: "Notifications on ✓", notifBlocked: "Notifications blocked in the browser",
        notifTitle: "5-1-1 pattern detected", notifBody: "Your contractions are following the 5-1-1 rhythm — consider contacting your healthcare provider.",
      };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "contraction", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  // Minuteur en direct : re-rend chaque seconde tant qu'une contraction est en cours
  useEffect(() => {
    if (!active) return;
    const id = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, [active]);

  const toggle = () => {
    if (active) {
      const stopTime = new Date();
      const durationMs = stopTime - active.start;
      const prevStart = log.length > 0 ? log[log.length - 1].start : null;
      const intervalMs = prevStart ? active.start - prevStart : null;
      const entry = {
        start: active.start,
        label: formatClock(active.start, lang),
        detail: `${M.duration} ${formatDuration(durationMs, lang)}${intervalMs ? ` · ${M.interval} ${formatDuration(intervalMs, lang)}` : ""}`,
      };
      const optimistic = makeOptimisticEntry(entry);
      setLog((l) => [...l, optimistic]);
      persistTrackerEntry("contraction", entry, session, setLog, optimistic.id);
      setSessionLog((s) => [...s, { start: active.start, durationMs, intervalMs }]);
      setActive(null);
    } else {
      setActive({ start: new Date() });
    }
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);

  // Détection approximative du motif "5-1-1" : contractions ~aux 5 min, durant ~1 min chacune,
  // observées sur une fenêtre d'au moins ~1 heure. Approximation informationnelle uniquement —
  // ne remplace jamais l'avis d'un professionnel de la santé.
  const five11 = useMemo(() => {
    if (sessionLog.length < 4) return false;
    const recent = sessionLog.slice(-8);
    const withInterval = recent.filter((e) => e.intervalMs != null);
    if (withInterval.length < 3) return false;
    const spanMs = recent[recent.length - 1].start - recent[0].start;
    if (spanMs < 50 * 60 * 1000) return false; // au moins ~50 min de suivi continu
    const intervalsOk = withInterval.every((e) => e.intervalMs <= 5.5 * 60 * 1000);
    const durationsOk = recent.every((e) => e.durationMs >= 50 * 1000);
    return intervalsOk && durationsOk;
  }, [sessionLog]);

  useEffect(() => {
    if (five11 && notifStatus === "granted" && !notifiedRef.current) {
      try { new Notification(M.notifTitle, { body: M.notifBody }); } catch {}
      notifiedRef.current = true;
    }
    if (!five11) notifiedRef.current = false;
  }, [five11, notifStatus]);

  const requestNotif = () => {
    if (typeof Notification === "undefined") return;
    Notification.requestPermission().then((p) => setNotifStatus(p));
  };

  return (
    <Card>
      <div style={{ background: "#FDF0F3", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <ContractionHeroIllu size={130} />
      </div>

      {five11 && (
        <div style={{
          display: "flex", gap: 10, alignItems: "flex-start", background: "#FDECEA", border: "1.5px solid #E8A79A",
          borderRadius: 14, padding: "12px 14px", marginBottom: 14,
        }}>
          <ShieldAlert size={20} color="#B3261E" style={{ flexShrink: 0, marginTop: 1 }} />
          <div>
            <p style={{ margin: "0 0 4px", fontSize: 13.5, fontWeight: 800, color: "#B3261E" }}>{M.alertTitle}</p>
            <p style={{ margin: 0, fontSize: 12.5, color: COLORS.text, lineHeight: 1.5 }}>{M.alertBody}</p>
          </div>
        </div>
      )}

      {active && (
        <div style={{ textAlign: "center", marginBottom: 10 }}>
          <div style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 700, color: COLORS.pink, marginBottom: 4 }}>
            <Clock size={14} /> {M.inProgress}
          </div>
          <div style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 30, fontWeight: 800, color: COLORS.pink, letterSpacing: 0.5 }}>
            {formatDuration(new Date() - active.start, lang)}
          </div>
        </div>
      )}

      <button onClick={toggle} style={{
        width: "100%", padding: "18px", borderRadius: 16, border: "none", cursor: "pointer",
        background: active ? COLORS.pink : "#FDF0F3", color: active ? "#fff" : COLORS.pink,
        fontWeight: 800, fontSize: 15,
      }}>
        {active ? M.save : M.start}
      </button>

      {notifStatus !== "unsupported" && notifStatus !== "granted" && (
        <button onClick={requestNotif} disabled={notifStatus === "denied"} style={{
          width: "100%", marginTop: 10, padding: "11px", borderRadius: 12, cursor: notifStatus === "denied" ? "default" : "pointer",
          border: `1.5px solid ${COLORS.teal}`, background: "#fff", color: notifStatus === "denied" ? COLORS.muted : COLORS.teal,
          fontWeight: 700, fontSize: 12.5, display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
        }}>
          <BellRing size={15} /> {notifStatus === "denied" ? M.notifBlocked : M.enableNotif}
        </button>
      )}
      {notifStatus === "granted" && (
        <p style={{ fontSize: 11.5, color: COLORS.muted, textAlign: "center", marginTop: 8, display: "flex", alignItems: "center", justifyContent: "center", gap: 5 }}>
          <Bell size={13} /> {M.notifOn}
        </p>
      )}

      <p style={{ fontSize: 12, color: COLORS.muted, lineHeight: 1.5, marginTop: 12 }}>{M.tip}</p>
      <TrackerLogList entries={log} emptyLabel={emptyLabel} onDelete={removeEntry} loaded={loaded} lang={lang} />
    </Card>
  );
}

