// Détermine la saison actuelle (hémisphère nord) — utilisée pour le thème « Vert », qui change
// automatiquement d'illustrations et de texte selon le moment de l'année, sans aucune action requise.
function getCurrentSeason() {
  const month = new Date().getMonth() + 1;
  if (month === 12 || month <= 2) return "winter";
  if (month >= 3 && month <= 5) return "spring";
  if (month >= 6 && month <= 8) return "summer";
  return "fall";
}

