// Diagramme visuel de l'arbre généalogique pour l'export PDF de l'album — boîtes reliées par des
// lignes convergentes (arrière-grands-parents → grands-parents → parents → bébé), à la manière
// d'un vrai arbre plutôt qu'une simple liste.
function FamilyTreePrintDiagram({ answers, lang, theme }) {
  const v = (id) => answers[id]?.text?.trim() || "—";
  const W = 520, H = 420;
  const row1Y = 15, row1H = 32, row2Y = 95, row2H = 34, row3Y = 185, row3H = 36, row4Y = 280, row4H = 42;
  const cx = [65, 195, 325, 455]; // centres des 4 colonnes (arrière-grands-parents + grands-parents)
  const mamanCx = (cx[0] + cx[1]) / 2, papaCx = (cx[2] + cx[3]) / 2;
  const bebeCx = (mamanCx + papaCx) / 2;

  const ggBoxes = [
    { id: "treeMaternalGGParentsGma", x: cx[0] },
    { id: "treeMaternalGGParentsGpa", x: cx[1] },
    { id: "treePaternalGGParentsGma", x: cx[2] },
    { id: "treePaternalGGParentsGpa", x: cx[3] },
  ];
  const gpBoxes = [
    { id: "treeMaternalGrandma", x: cx[0] },
    { id: "treeMaternalGrandpa", x: cx[1] },
    { id: "treePaternalGrandma", x: cx[2] },
    { id: "treePaternalGrandpa", x: cx[3] },
  ];

  const boxDiv = (id, x, y, h, w, bold) => (
    <div key={id} style={{
      position: "absolute", left: x - w / 2, top: y, width: w, height: h,
      border: `1px solid ${theme.accent}`, borderRadius: 4, background: "#fff",
      display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center",
      fontSize: w > 130 ? 11.5 : 9, fontWeight: bold ? 800 : 700, color: COLORS.text, padding: "2px 6px",
      boxSizing: "border-box", lineHeight: 1.25,
    }}>{v(id)}</div>
  );

  return (
    <div style={{ position: "relative", width: W, height: H, margin: "0 auto" }}>
      <svg width={W} height={H} style={{ position: "absolute", top: 0, left: 0 }}>
        {cx.map((x, i) => (
          <line key={`gg-gp-${i}`} x1={x} y1={row1Y + row1H} x2={x} y2={row2Y} stroke={theme.accent} strokeOpacity={0.55} strokeWidth={1.3} />
        ))}
        <line x1={cx[0]} y1={row2Y + row2H} x2={mamanCx} y2={row3Y} stroke={theme.accent} strokeOpacity={0.55} strokeWidth={1.3} />
        <line x1={cx[1]} y1={row2Y + row2H} x2={mamanCx} y2={row3Y} stroke={theme.accent} strokeOpacity={0.55} strokeWidth={1.3} />
        <line x1={cx[2]} y1={row2Y + row2H} x2={papaCx} y2={row3Y} stroke={theme.accent} strokeOpacity={0.55} strokeWidth={1.3} />
        <line x1={cx[3]} y1={row2Y + row2H} x2={papaCx} y2={row3Y} stroke={theme.accent} strokeOpacity={0.55} strokeWidth={1.3} />
        <line x1={mamanCx} y1={row3Y + row3H} x2={bebeCx} y2={row4Y} stroke={theme.accent} strokeOpacity={0.7} strokeWidth={1.5} />
        <line x1={papaCx} y1={row3Y + row3H} x2={bebeCx} y2={row4Y} stroke={theme.accent} strokeOpacity={0.7} strokeWidth={1.5} />
      </svg>
      {ggBoxes.map((b) => boxDiv(b.id, b.x, row1Y, row1H, 110, false))}
      {gpBoxes.map((b) => boxDiv(b.id, b.x, row2Y, row2H, 110, false))}
      {boxDiv("treeMom", mamanCx, row3Y, row3H, 130, true)}
      {boxDiv("treeDad", papaCx, row3Y, row3H, 130, true)}
      <div style={{
        position: "absolute", left: bebeCx - 80, top: row4Y, width: 160, height: row4H,
        border: `1.5px solid ${theme.accent}`, borderRadius: 4, background: theme.bg,
        display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center",
        fontSize: 13, fontWeight: 800, color: theme.accent,
      }}>{lang === "fr" ? "Bébé" : lang === "es" ? "Bebé" : "Baby"}</div>
    </div>
  );
}

// Chemins publics des fichiers de l'album souvenir (à téléverser dans /public sur GitHub, exactement
// sous ces noms) — 6 PDF (3 couleurs × FR/EN, logo Lantern Days retiré) et leurs images d'aperçu.
const ALBUM_PDF = {
  beige: { fr: "/album-bebe-beige-fr.pdf", en: "/album-bebe-beige-en.pdf" },
  rose: { fr: "/album-bebe-rose-fr.pdf", en: "/album-bebe-rose-en.pdf" },
  bleu: { fr: "/album-bebe-bleu-fr.pdf", en: "/album-bebe-bleu-en.pdf" },
};
// Pour chaque couleur : la couverture en premier, puis quelques pages intérieures variées — utilisé
// pour le défilé automatique sur la carte de chaque modèle (aperçu directement dans sa propre couleur).
const ALBUM_PREVIEW_IMAGES = {
  beige: ["/album-preview-beige-1.jpg", "/album-preview-beige-2.jpg", "/album-preview-beige-3.jpg", "/album-preview-beige-4.jpg", "/album-preview-beige-5.jpg", "/album-preview-beige-6.jpg"],
  rose: ["/album-preview-rose-1.jpg", "/album-preview-rose-2.jpg", "/album-preview-rose-3.jpg", "/album-preview-rose-4.jpg", "/album-preview-rose-5.jpg", "/album-preview-rose-6.jpg"],
  bleu: ["/album-preview-bleu-1.jpg", "/album-preview-bleu-2.jpg", "/album-preview-bleu-3.jpg", "/album-preview-bleu-4.jpg", "/album-preview-bleu-5.jpg", "/album-preview-bleu-6.jpg"],
};

function AlbumPreviewCarousel({ images, intervalMs = 2600 }) {
  const [index, setIndex] = useState(0);
  useEffect(() => {
    setIndex(0); // repart du début (la couverture) si la liste d'images change (ex. changement de couleur)
    const id = setInterval(() => setIndex((i) => (i + 1) % images.length), intervalMs);
    return () => clearInterval(id);
  }, [images, intervalMs]);
  return (
    <div style={{
      position: "relative", width: "100%", aspectRatio: "0.775",
      borderRadius: 14, overflow: "hidden", background: "#FDF0F3",
      boxShadow: "0 6px 16px rgba(47,72,88,0.16)", border: `1px solid ${COLORS.line}`,
    }}>
      {images.map((src, i) => (
        <img
          key={src} src={src} alt="" loading={i === 0 ? "eager" : "lazy"}
          style={{
            position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover",
            opacity: i === index ? 1 : 0, transition: "opacity 1.1s ease",
          }}
          onError={(e) => { e.target.style.display = "none"; }}
        />
      ))}
      <div style={{
        position: "absolute", left: 0, right: 0, bottom: 0, display: "flex", justifyContent: "center", gap: 4, padding: "6px 0",
        background: "linear-gradient(to top, rgba(0,0,0,0.28), transparent)",
      }}>
        {images.map((_, i) => (
          <span key={i} style={{
            width: 4, height: 4, borderRadius: "50%",
            background: i === index ? "#fff" : "rgba(255,255,255,0.5)",
          }} />
        ))}
      </div>
    </div>
  );
}

function AlbumSouvenirShowcase({ lang, isMember, goTo, session }) {
  const L = lang === "fr"
    ? {
        title: "Mon album de bébé", subtitle: "Un vrai livre-souvenir à remplir vous-même, de la grossesse à 5 ans — 25 pages, inclus gratuitement avec votre abonnement.",
        bullets: ["Sommaire cliquable, facile à naviguer", "Compatible GoodNotes, Notability, iPad et Android", "Imprimable si vous préférez le papier"],
        colorNames: { beige: "Beige", rose: "Rose", bleu: "Bleu" },
        download: "Télécharger", enNote: "Version anglaise du PDF",
        uploadTitle: "Mon album complété", uploadDesc: "Une fois votre album rempli, téléversez-en une photo ou le PDF pour le garder en sécurité ici.",
        attachBtn: "Choisir une photo ou un PDF", changeFile: "Changer le fichier", saveBtn: "Sauvegarder",
        empty: "Aucun album téléversé pour l'instant.", remove: "Retirer",
        errorAdd: "Impossible d'ajouter ce fichier pour le moment.", errorRemove: "Impossible de retirer ce fichier pour le moment.",
        errorNoSession: "Vous devez être connectée pour sauvegarder un fichier de façon permanente.",
      }
    : lang === "es"
    ? {
        title: "Mi álbum de recuerdos del bebé", subtitle: "Un verdadero libro de recuerdos para completar tú misma, desde el embarazo hasta los 5 años — 25 páginas, incluido gratis con tu membresía.",
        bullets: ["Índice con enlaces, fácil de navegar", "Compatible con GoodNotes, Notability, iPad y Android", "Imprimible si prefieres el papel"],
        colorNames: { beige: "Beige", rose: "Rosa", bleu: "Azul" },
        download: "Descargar", enNote: "El PDF está disponible en inglés",
        uploadTitle: "Mi álbum completado", uploadDesc: "Una vez que hayas llenado tu álbum, sube una foto o el PDF para guardarlo aquí de forma segura.",
        attachBtn: "Elegir una foto o un PDF", changeFile: "Cambiar el archivo", saveBtn: "Guardar",
        empty: "Aún no se ha subido ningún álbum.", remove: "Quitar",
        errorAdd: "No se pudo agregar este archivo por ahora.", errorRemove: "No se pudo quitar este archivo por ahora.",
        errorNoSession: "Debes iniciar sesión para guardar un archivo de forma permanente.",
      }
    : {
        title: "My baby memory album", subtitle: "A real memory book to fill in yourself, from pregnancy to age 5 — 25 pages, included free with your membership.",
        bullets: ["Clickable table of contents, easy to navigate", "Compatible with GoodNotes, Notability, iPad and Android", "Printable if you prefer paper"],
        colorNames: { beige: "Beige", rose: "Pink", bleu: "Blue" },
        download: "Download", enNote: "",
        uploadTitle: "My completed album", uploadDesc: "Once your album is filled in, upload a photo or the PDF to keep it safe here.",
        attachBtn: "Choose a photo or PDF", changeFile: "Change file", saveBtn: "Save",
        empty: "No album uploaded yet.", remove: "Remove",
        errorAdd: "Couldn't add this file right now.", errorRemove: "Couldn't remove this file right now.",
        errorNoSession: "You need to be signed in to permanently save a file.",
      };

  const pdfLang = lang === "fr" ? "fr" : "en";
  const hasSession = !!(session?.access_token && session?.user?.id);

  // ---- Téléversement de l'album complété (réutilise la table "documents" existante, catégorie "album") ----
  const [uploads, setUploads] = useState([]);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchDocuments(session.user.id, session.access_token)
      .then((rows) => setUploads(rows.map(mapDocumentRow).filter((d) => d.category === "album")))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const [pendingFile, setPendingFile] = useState(null);
  const [pendingPreview, setPendingPreview] = useState(null);
  const [saving, setSaving] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const fileInputRef = useRef(null);

  const handleFile = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setErrorMsg("");
    setPendingFile(file);
    setPendingPreview(URL.createObjectURL(file));
  };
  const removePendingFile = () => {
    setPendingFile(null);
    if (pendingPreview) URL.revokeObjectURL(pendingPreview);
    setPendingPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };
  const saveUpload = async () => {
    if (!pendingFile) return;
    setErrorMsg(""); setSaving(true);
    if (hasSession) {
      try {
        const photoUrl = await supabaseUploadPhoto(pendingFile, session.user.id, session.access_token);
        const newDoc = { label: pendingFile.name, photo: photoUrl, category: "album" };
        const row = await supabaseAddDocument(newDoc, session.user.id, session.access_token);
        setUploads((u) => [mapDocumentRow(row), ...u]);
        removePendingFile();
      } catch (e) { setErrorMsg(L.errorAdd); }
    } else {
      setErrorMsg(L.errorNoSession);
    }
    setSaving(false);
  };
  const removeUpload = async (id) => {
    setErrorMsg("");
    if (hasSession) {
      try {
        await supabaseDeleteDocument(id, session.access_token);
        setUploads((u) => u.filter((x) => x.id !== id));
      } catch (e) { setErrorMsg(L.errorRemove); }
    }
  };

  if (!isMember) {
    return (
      <Card>
        <div style={{ background: "#FDF0F3", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
          <Illustration type="teddyBearIllu" size={130} />
        </div>
        <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 18, color: COLORS.teal, textAlign: "center" }}>{L.title}</h3>
        <p style={{ margin: "0 0 16px", fontSize: 13, color: COLORS.muted, lineHeight: 1.5, textAlign: "center" }}>{L.subtitle}</p>
        <LockedContent lang={lang} goTo={goTo} />
      </Card>
    );
  }

  return (
    <Card>
      <div style={{ background: "#FDF0F3", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <Illustration type="teddyBearIllu" size={130} />
      </div>
      <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 18, color: COLORS.teal, textAlign: "center" }}>{L.title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 13, color: COLORS.muted, lineHeight: 1.5, textAlign: "center" }}>{L.subtitle}</p>
      <ul style={{ margin: "0 0 20px", padding: 0, listStyle: "none" }}>
        {L.bullets.map((b, i) => (
          <li key={i} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12.5, color: COLORS.text, marginBottom: 6 }}>
            <span style={{ color: COLORS.pink, fontWeight: 800 }}>◆</span> {b}
          </li>
        ))}
      </ul>

      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 22 }}>
        {["beige", "rose", "bleu"].map((color) => (
          <div key={color} style={{
            flex: "1 1 150px", minWidth: 140, border: `1px solid ${COLORS.line}`, borderRadius: 14,
            overflow: "hidden", background: "#fff", display: "flex", flexDirection: "column",
          }}>
            <div style={{ padding: 6 }}>
              <AlbumPreviewCarousel images={ALBUM_PREVIEW_IMAGES[color]} />
            </div>
            <div style={{ padding: "4px 12px 12px", textAlign: "center" }}>
              <p style={{ margin: "0 0 8px", fontSize: 13, fontWeight: 700, color: COLORS.text }}>{L.colorNames[color]}</p>
              <a
                href={ALBUM_PDF[color][pdfLang]} download
                style={{
                  display: "block", background: COLORS.pink, color: "#fff", textDecoration: "none",
                  borderRadius: 999, padding: "8px 10px", fontSize: 12.5, fontWeight: 700,
                }}
              >{L.download}</a>
              {pdfLang === "en" && L.enNote && (
                <p style={{ margin: "6px 0 0", fontSize: 10.5, color: COLORS.muted, fontStyle: "italic" }}>{L.enNote}</p>
              )}
            </div>
          </div>
        ))}
      </div>

      <div style={{ borderTop: `1px solid ${COLORS.line}`, paddingTop: 18 }}>
        <p style={{ margin: "0 0 4px", fontSize: 14.5, fontWeight: 700, color: COLORS.text }}>{L.uploadTitle}</p>
        <p style={{ margin: "0 0 12px", fontSize: 12.5, color: COLORS.muted, lineHeight: 1.5 }}>{L.uploadDesc}</p>

        <label style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 8, width: "100%", padding: "13px",
          borderRadius: 14, border: `1.5px dashed ${COLORS.pink}80`, background: pendingFile ? "#fff" : "#FDF0F3",
          fontSize: 13, color: COLORS.pink, fontWeight: 700, cursor: "pointer", marginBottom: 8, boxSizing: "border-box",
        }}>
          📎 {pendingFile ? `${L.changeFile} — ${pendingFile.name}` : L.attachBtn}
          <input ref={fileInputRef} type="file" accept="image/*,application/pdf" onChange={handleFile} style={{ display: "none" }} />
        </label>

        {pendingFile && (
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
            {pendingPreview && pendingFile.type.startsWith("image") && (
              <img src={pendingPreview} alt="" style={{ width: 44, height: 44, borderRadius: 10, objectFit: "cover", flexShrink: 0 }} />
            )}
            <button onClick={saveUpload} disabled={saving} style={{
              flex: 1, padding: "10px", borderRadius: 10, border: "none", background: COLORS.pink, color: "#fff",
              fontWeight: 700, fontSize: 13, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1,
            }}>{saving ? "…" : L.saveBtn}</button>
          </div>
        )}

        {errorMsg && <p style={{ fontSize: 11.5, color: "#B3261E", marginBottom: 10 }}>{errorMsg}</p>}

        {loaded && uploads.length === 0 && (
          <p style={{ fontSize: 12, color: COLORS.muted, fontStyle: "italic", textAlign: "center", margin: "8px 0 0" }}>{L.empty}</p>
        )}
        {uploads.map((u) => (
          <div key={u.id} style={{
            display: "flex", alignItems: "center", gap: 10, background: COLORS.cream, borderRadius: 10,
            padding: "8px 12px", marginTop: 8,
          }}>
            {u.photo && <img src={u.photo} alt="" style={{ width: 36, height: 36, borderRadius: 8, objectFit: "cover", flexShrink: 0 }} />}
            <span style={{ flex: 1, fontSize: 12.5, color: COLORS.text, fontWeight: 600, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{u.label}</span>
            <button onClick={() => removeUpload(u.id)} style={{ background: "none", border: "none", color: COLORS.muted, cursor: "pointer", padding: 2, display: "flex", flexShrink: 0 }}>
              <X size={14} />
            </button>
          </div>
        ))}
      </div>
    </Card>
  );
}


function AppointmentManager({ lang, isMember, goTo, embedded = false, session, children: registeredKids }) {
  const [appointments, setAppointments] = useState([]);
  const [form, setForm] = useState({ person: "maman", childName: "", title: "", date: "", time: "", location: "", notes: "" });
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const hasSession = !!(session?.access_token && session?.user?.id);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchAppointments(session.user.id, session.access_token)
      .then((rows) => setAppointments(rows.map(mapAppointmentRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const L = lang === "fr"
    ? {
        title: "Rendez-vous & horaire familial", subtitle: "Gardez en un seul endroit les rendez-vous de maman et des enfants.",
        addBtn: "+ Ajouter un rendez-vous", person: "Pour qui ?", maman: "Maman", papa: "Papa/Partenaire", enfant: "Enfant",
        childName: "Prénom de l'enfant", parentNameLabel: "Prénom (optionnel)", appTitle: "Titre du rendez-vous", appTitlePh: "Ex. Visite postnatale, vaccin 2 mois...",
        date: "Date", time: "Heure", location: "Lieu (optionnel)", notes: "Notes (optionnel)",
        save: "Enregistrer", cancel: "Annuler", empty: "Aucun rendez-vous à venir. Ajoutez-en un pour commencer.",
        exampleLabel: "Exemple — ajoutez le vôtre ci-dessus",
        upcoming: "À venir", past: "Passés", remove: "Retirer", edit: "Modifier", share: "Partager",
        shareTitle: "Rendez-vous", shareText: (t, d, tm, l) => `Rendez-vous : ${t}\nDate : ${d}${tm ? ` à ${tm}` : ""}${l ? `\nLieu : ${l}` : ""}`,
        shareAllTitle: "Rendez-vous à venir", shareAllBtn: "📤 Partager tous les rendez-vous à venir",
        errorAdd: "Impossible d'ajouter ce rendez-vous pour le moment.", errorRemove: "Impossible de retirer ce rendez-vous.", errorUpdate: "Impossible de modifier ce rendez-vous.",
        apptWord: "rendez-vous", apptsWord: "rendez-vous",
        reminderTitle: "Rappel de rendez-vous", reminderIn2: "Dans 2 jours", reminderTomorrow: "Demain", reminderToday: "Aujourd'hui",
        enableNotif: "Activer les rappels de rendez-vous", notifOn: "Rappels activés ✓", notifBlocked: "Notifications bloquées dans le navigateur",
        notifBody: (t, d) => `Rappel : ${t} le ${d}`,
      }
    : lang === "es"
    ? {
        title: "Citas y horario familiar", subtitle: "Mantén en un solo lugar las citas de mamá y de los niños.",
        addBtn: "+ Agregar una cita", person: "¿Para quién?", maman: "Mamá", papa: "Papá/Pareja", enfant: "Hijo/a",
        childName: "Nombre del hijo/a", parentNameLabel: "Nombre (opcional)", appTitle: "Título de la cita", appTitlePh: "Ej. Visita posnatal, vacuna 2 meses...",
        date: "Fecha", time: "Hora", location: "Lugar (opcional)", notes: "Notas (opcional)",
        save: "Guardar", cancel: "Cancelar", empty: "Aún no hay citas próximas. Agrega una para comenzar.",
        exampleLabel: "Ejemplo — agrega la tuya arriba",
        upcoming: "Próximas", past: "Pasadas", remove: "Quitar", edit: "Modificar", share: "Compartir",
        shareTitle: "Cita", shareText: (t, d, tm, l) => `Cita : ${t}\nFecha : ${d}${tm ? ` a las ${tm}` : ""}${l ? `\nLugar : ${l}` : ""}`,
        shareAllTitle: "Próximas citas", shareAllBtn: "📤 Compartir todas las próximas citas",
        errorAdd: "No se pudo agregar esta cita por ahora.", errorRemove: "No se pudo quitar esta cita.", errorUpdate: "No se pudo modificar esta cita.",
        apptWord: "cita", apptsWord: "citas",
        reminderTitle: "Recordatorio de cita", reminderIn2: "En 2 días", reminderTomorrow: "Mañana", reminderToday: "Hoy",
        enableNotif: "Activar recordatorios de citas", notifOn: "Recordatorios activados ✓", notifBlocked: "Notificaciones bloqueadas en el navegador",
        notifBody: (t, d) => `Recordatorio: ${t} el ${d}`,
      }
    : {
        title: "Appointments & family schedule", subtitle: "Keep mom's and the kids' appointments all in one place.",
        addBtn: "+ Add an appointment", person: "For whom?", maman: "Mom", papa: "Dad/Partner", enfant: "Child",
        childName: "Child's first name", parentNameLabel: "First name (optional)", appTitle: "Appointment title", appTitlePh: "E.g. Postnatal visit, 2-month vaccine...",
        date: "Date", time: "Time", location: "Location (optional)", notes: "Notes (optional)",
        save: "Save", cancel: "Cancel", empty: "No upcoming appointments. Add one to get started.",
        exampleLabel: "Example — add your own above",
        upcoming: "Upcoming", past: "Past", remove: "Remove", edit: "Edit", share: "Share",
        shareTitle: "Appointment", shareText: (t, d, tm, l) => `Appointment: ${t}\nDate: ${d}${tm ? ` at ${tm}` : ""}${l ? `\nLocation: ${l}` : ""}`,
        shareAllTitle: "Upcoming appointments", shareAllBtn: "📤 Share all upcoming appointments",
        errorAdd: "Couldn't add this appointment right now.", errorRemove: "Couldn't remove this appointment.", errorUpdate: "Couldn't update this appointment.",
        apptWord: "appointment", apptsWord: "appointments",
        reminderTitle: "Appointment reminder", reminderIn2: "In 2 days", reminderTomorrow: "Tomorrow", reminderToday: "Today",
        enableNotif: "Turn on appointment reminders", notifOn: "Reminders on ✓", notifBlocked: "Notifications blocked in the browser",
        notifBody: (t, d) => `Reminder: ${t} on ${d}`,
      };

  const EXAMPLE_APPT = lang === "fr"
    ? { person: "enfant", childName: "Bébé", title: "Vaccin 2 mois", date: "2026-09-14", time: "10 h 00", location: "CLSC du quartier" }
    : lang === "es"
    ? { person: "enfant", childName: "Bebé", title: "Vacuna 2 meses", date: "2026-09-14", time: "10:00 AM", location: "Clínica local" }
    : { person: "enfant", childName: "Baby", title: "2-month vaccine", date: "2026-09-14", time: "10:00 AM", location: "Local clinic" };

  const personColors = { maman: COLORS.pink, papa: COLORS.blue, enfant: COLORS.ochre };

  const addAppointment = async () => {
    if (!form.title.trim() || !form.date) return;
    setErrorMsg("");
    if (hasSession) {
      setSaving(true);
      try {
        const row = await supabaseAddAppointment(form, session.user.id, session.access_token);
        setAppointments((a) => [...a, mapAppointmentRow(row)]);
        setForm({ person: "maman", childName: "", title: "", date: "", time: "", location: "", notes: "" });
        setShowForm(false);
      } catch (err) {
        setErrorMsg(L.errorAdd);
      }
      setSaving(false);
    } else {
      setAppointments((a) => [...a, { ...form, id: `local-${Date.now()}` }]);
      setForm({ person: "maman", childName: "", title: "", date: "", time: "", location: "", notes: "" });
      setShowForm(false);
    }
  };
  const removeAppointment = async (id) => {
    setErrorMsg("");
    if (hasSession && typeof id === "string" && !id.startsWith("local-")) {
      try {
        await supabaseDeleteAppointment(id, session.access_token);
        setAppointments((a) => a.filter((x) => x.id !== id));
      } catch (err) {
        setErrorMsg(L.errorRemove);
      }
    } else {
      setAppointments((a) => a.filter((x) => x.id !== id));
    }
  };
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState(null);
  const startEditAppt = (appt) => { setEditingId(appt.id); setEditForm({ ...appt }); };
  const cancelEditAppt = () => { setEditingId(null); setEditForm(null); };
  const saveEditAppt = async () => {
    if (!editForm.title.trim() || !editForm.date) return;
    setAppointments((a) => a.map((x) => (x.id === editingId ? { ...x, ...editForm } : x)));
    if (hasSession && typeof editingId === "string" && !editingId.startsWith("local-")) {
      try { await supabaseUpdateAppointment(editingId, editForm, session.access_token); } catch { setErrorMsg(L.errorUpdate); }
    }
    setEditingId(null);
    setEditForm(null);
  };
  const whoLabel = (appt) => {
    if (appt.person === "enfant") return appt.childName || L.enfant;
    const base = appt.person === "maman" ? L.maman : L.papa;
    return appt.childName ? `${base} — ${appt.childName}` : base;
  };
  const shareAppointment = (appt) => {
    const who = whoLabel(appt);
    const text = `${L.shareText(appt.title, appt.date, appt.time, appt.location)}\n${L.person} ${who}${appt.notes ? `\n${appt.notes}` : ""}`;
    if (navigator.share) {
      navigator.share({ title: L.shareTitle, text }).catch(() => {});
    } else {
      const mailto = `mailto:?subject=${encodeURIComponent(L.shareTitle + " — " + appt.title)}&body=${encodeURIComponent(text)}`;
      window.open(mailto, "_blank");
    }
  };
  const shareAllUpcoming = (list) => {
    const text = list.map((appt) => {
      const who = whoLabel(appt);
      return `${L.shareText(appt.title, appt.date, appt.time, appt.location)}\n${L.person} ${who}${appt.notes ? `\n${appt.notes}` : ""}`;
    }).join("\n\n");
    if (navigator.share) {
      navigator.share({ title: L.shareAllTitle, text }).catch(() => {});
    } else {
      const mailto = `mailto:?subject=${encodeURIComponent(L.shareAllTitle)}&body=${encodeURIComponent(text)}`;
      window.open(mailto, "_blank");
    }
  };

  const today = new Date().toISOString().slice(0, 10);
  const sorted = appointments.slice().sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));
  const upcoming = sorted.filter((a) => a.date >= today);
  const past = sorted.filter((a) => a.date < today);

  // ---- Rappel automatique de rendez-vous (2 jours avant) ----
  // Approche best-effort côté navigateur : cette appli web n'a pas d'infrastructure de notification
  // push (pas de service worker), donc le rappel se déclenche quand la personne ouvre l'appli, pas
  // en arrière-plan téléphone fermé. On affiche toujours un bandeau visuel, et en plus une notification
  // navigateur si la permission a été accordée — chaque rendez-vous n'est notifié qu'une seule fois
  // (mémorisé dans le navigateur) pour éviter de spammer à chaque ouverture.
  const [notifStatus, setNotifStatus] = useState(
    typeof Notification !== "undefined" ? Notification.permission : "unsupported"
  );
  const daysUntil = (dateStr) => Math.round((new Date(dateStr + "T00:00:00") - new Date(today + "T00:00:00")) / 86400000);
  const dueSoon = upcoming.filter((a) => { const d = daysUntil(a.date); return d >= 0 && d <= 2; });

  useEffect(() => {
    if (notifStatus !== "granted" || dueSoon.length === 0) return;
    let notifiedIds = [];
    try { notifiedIds = JSON.parse(localStorage.getItem(mmbScopedKey("mmb_appt_notified", session)) || "[]"); } catch {}
    let changed = false;
    dueSoon.forEach((a) => {
      const key = `${a.id}-${a.date}`;
      if (notifiedIds.includes(key)) return;
      try { new Notification(L.reminderTitle, { body: L.notifBody(a.title, a.date) }); } catch {}
      notifiedIds.push(key);
      changed = true;
    });
    if (changed) {
      try { localStorage.setItem(mmbScopedKey("mmb_appt_notified", session), JSON.stringify(notifiedIds.slice(-100))); } catch {}
    }
  }, [notifStatus, dueSoon.map((a) => a.id).join(",")]);

  const requestApptNotif = () => {
    if (typeof Notification === "undefined") return;
    Notification.requestPermission().then((p) => setNotifStatus(p));
  };
  const reminderLabel = (dateStr) => {
    const d = daysUntil(dateStr);
    if (d === 0) return L.reminderToday;
    if (d === 1) return L.reminderTomorrow;
    return L.reminderIn2;
  };

  const inputStyle = { width: "100%", padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13.5, boxSizing: "border-box" };
  const labelStyle = { display: "flex", flexDirection: "column", gap: 6, fontSize: 12.5, color: COLORS.muted, fontWeight: 600, marginBottom: 12 };

  const AppointmentCard = ({ appt, faded, hideRemove }) => {
    const who = whoLabel(appt);
    const color = personColors[appt.person];

    if (editingId === appt.id) {
      return (
        <Card style={{ borderLeft: `4px solid ${color}` }}>
          <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
            {["maman", "papa", "enfant"].map((p) => (
              <button key={p} onClick={() => setEditForm({ ...editForm, person: p, childName: "" })} style={{
                flex: 1, padding: "9px", borderRadius: 10, cursor: "pointer",
                border: `1px solid ${editForm.person === p ? personColors[p] : COLORS.line}`,
                background: editForm.person === p ? personColors[p] : "#fff",
                color: editForm.person === p ? "#fff" : COLORS.text, fontWeight: 700, fontSize: 13,
              }}>{p === "maman" ? L.maman : p === "papa" ? L.papa : L.enfant}</button>
            ))}
          </div>
          {(editForm.person === "maman" || editForm.person === "papa") && (
            <label style={labelStyle}>{L.parentNameLabel}
              <input style={inputStyle} value={editForm.childName} onChange={(e) => setEditForm({ ...editForm, childName: e.target.value })} />
            </label>
          )}
          {editForm.person === "enfant" && (
            <label style={labelStyle}>{L.childName}
              {registeredKids && registeredKids.length > 0 && (
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
                  {registeredKids.map((ch) => (
                    <button key={ch.id} type="button" onClick={() => setEditForm({ ...editForm, childName: ch.name })} style={{
                      padding: "6px 13px", borderRadius: 999, fontSize: 12.5, fontWeight: 700, cursor: "pointer",
                      border: `1px solid ${editForm.childName === ch.name ? COLORS.teal : COLORS.line}`,
                      background: editForm.childName === ch.name ? COLORS.teal : "#fff",
                      color: editForm.childName === ch.name ? "#fff" : COLORS.text,
                    }}>{ch.name}</button>
                  ))}
                </div>
              )}
              <input style={inputStyle} value={editForm.childName} onChange={(e) => setEditForm({ ...editForm, childName: e.target.value })} />
            </label>
          )}
          <label style={labelStyle}>{L.appTitle}
            <input style={inputStyle} value={editForm.title} onChange={(e) => setEditForm({ ...editForm, title: e.target.value })} />
          </label>
          <div style={{ display: "flex", gap: 10 }}>
            <label style={{ ...labelStyle, flex: 1 }}>{L.date}
              <input type="date" style={inputStyle} value={editForm.date} onChange={(e) => setEditForm({ ...editForm, date: e.target.value })} />
            </label>
            <label style={{ ...labelStyle, flex: 1 }}>{L.time}
              <TimeSelect value={editForm.time} onChange={(t) => setEditForm({ ...editForm, time: t })} />
            </label>
          </div>
          <label style={labelStyle}>{L.location}
            <input style={inputStyle} value={editForm.location} onChange={(e) => setEditForm({ ...editForm, location: e.target.value })} />
          </label>
          <label style={labelStyle}>{L.notes}
            <input style={inputStyle} value={editForm.notes} onChange={(e) => setEditForm({ ...editForm, notes: e.target.value })} />
          </label>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={saveEditAppt} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "10px 20px", borderRadius: 10, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{L.save}</button>
            <button onClick={cancelEditAppt} style={{ background: "transparent", color: COLORS.muted, border: `1px solid ${COLORS.line}`, padding: "10px 20px", borderRadius: 10, fontWeight: 600, fontSize: 14, cursor: "pointer" }}>{L.cancel}</button>
          </div>
        </Card>
      );
    }

    return (
      <div style={{
        display: "flex", gap: 12, alignItems: "flex-start", background: faded ? COLORS.cream : `${color}14`,
        borderRadius: 14, padding: "12px 14px", borderLeft: `4px solid ${color}`, opacity: faded ? 0.7 : 1,
      }}>
        <div style={{
          minWidth: 52, textAlign: "center", background: color, color: "#fff", borderRadius: 10, padding: "6px 4px", flexShrink: 0,
        }}>
          <div style={{ fontSize: 15, fontWeight: 800, lineHeight: 1.1 }}>{appt.date?.slice(8, 10)}</div>
          <div style={{ fontSize: 9.5, fontWeight: 700, textTransform: "uppercase" }}>{appt.date?.slice(5, 7)}/{appt.date?.slice(0, 4)}</div>
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 3 }}>
            <span style={{ fontWeight: 700, fontSize: 14, color: COLORS.text }}>{appt.title}</span>
            <span style={{
              background: color, color: "#fff", fontSize: 9.5, fontWeight: 700,
              padding: "2px 8px", borderRadius: 999, textTransform: "uppercase",
            }}>{who}</span>
          </div>
          <p style={{ margin: 0, fontSize: 12.5, color: COLORS.muted }}>
            {appt.time && `${appt.time} · `}{appt.location}
          </p>
          {appt.notes && <p style={{ margin: "4px 0 0", fontSize: 12, color: COLORS.text }}>{appt.notes}</p>}
        </div>
        {!hideRemove && (
          <div style={{ display: "flex", flexDirection: "column", gap: 6, alignItems: "flex-end", flexShrink: 0 }}>
            <button onClick={() => shareAppointment(appt)} style={{ background: "none", border: "none", color: COLORS.teal, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>{L.share}</button>
            <button onClick={() => startEditAppt(appt)} style={{ background: "none", border: "none", color: COLORS.teal, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>{L.edit}</button>
            <button onClick={() => removeAppointment(appt.id)} style={{ background: "none", border: "none", color: COLORS.muted, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>{L.remove}</button>
          </div>
        )}
      </div>
    );
  };

  if (!isMember && !embedded) {
    return (
      <div>
        <SectionHero sectionKey="rdv" lang={lang} />
        <ToyDivider />
        <LockedContent lang={lang} goTo={goTo} />
      </div>
    );
  }

  return (
    <div>
      <div style={{ background: "#EAF2F8", borderRadius: 18, padding: "18px 16px", textAlign: "center", marginBottom: 16 }}>
        <AppointmentHeroIllu size={140} />
      </div>
      <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 18, color: COLORS.teal }}>{L.title}</h3>
      <p style={{ margin: "0 0 16px", fontSize: 13, color: COLORS.muted, lineHeight: 1.5 }}>{L.subtitle}</p>

      {dueSoon.length > 0 && (
        <div style={{ background: "#EAF2F8", border: `1.5px solid ${COLORS.teal}55`, borderRadius: 14, padding: "12px 14px", marginBottom: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 8 }}>
            <BellRing size={16} color={COLORS.teal} />
            <span style={{ fontSize: 13, fontWeight: 800, color: COLORS.teal }}>{L.reminderTitle}</span>
          </div>
          {dueSoon.map((a) => (
            <div key={a.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 12.5, padding: "4px 0", color: COLORS.text }}>
              <span>{a.title} — {whoLabel(a)}</span>
              <span style={{ fontWeight: 700, color: COLORS.teal }}>{reminderLabel(a.date)}</span>
            </div>
          ))}
          {notifStatus !== "unsupported" && notifStatus !== "granted" && (
            <button onClick={requestApptNotif} disabled={notifStatus === "denied"} style={{
              width: "100%", marginTop: 8, padding: "9px", borderRadius: 10, cursor: notifStatus === "denied" ? "default" : "pointer",
              border: `1.5px solid ${COLORS.teal}`, background: "#fff", color: notifStatus === "denied" ? COLORS.muted : COLORS.teal,
              fontWeight: 700, fontSize: 12, display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
            }}>
              <Bell size={14} /> {notifStatus === "denied" ? L.notifBlocked : L.enableNotif}
            </button>
          )}
          {notifStatus === "granted" && (
            <p style={{ fontSize: 11, color: COLORS.muted, margin: "8px 0 0", display: "flex", alignItems: "center", gap: 5 }}>
              <Bell size={12} /> {L.notifOn}
            </p>
          )}
        </div>
      )}

      {!showForm ? (
        <button onClick={() => setShowForm(true)} style={{
          width: "100%", padding: "13px", borderRadius: 12, border: "none", background: COLORS.teal,
          color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer", marginBottom: upcoming.length > 0 ? 10 : 20,
        }}>{L.addBtn}</button>
      ) : null}
      {!showForm && upcoming.length > 0 && (
        <button onClick={() => shareAllUpcoming(upcoming)} style={{
          width: "100%", padding: "13px", borderRadius: 12, border: `1.5px solid ${COLORS.teal}`, background: "#fff",
          color: COLORS.teal, fontWeight: 700, fontSize: 14, cursor: "pointer", marginBottom: 20,
        }}>{L.shareAllBtn}</button>
      )}
      {showForm && (
        <Card style={{ marginBottom: 20 }}>
          <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
            {["maman", "papa", "enfant"].map((p) => (
              <button key={p} onClick={() => setForm({ ...form, person: p, childName: "" })} style={{
                flex: 1, padding: "9px", borderRadius: 10, cursor: "pointer",
                border: `1px solid ${form.person === p ? personColors[p] : COLORS.line}`,
                background: form.person === p ? personColors[p] : "#fff",
                color: form.person === p ? "#fff" : COLORS.text, fontWeight: 700, fontSize: 13,
              }}>{p === "maman" ? L.maman : p === "papa" ? L.papa : L.enfant}</button>
            ))}
          </div>
          {(form.person === "maman" || form.person === "papa") && (
            <label style={labelStyle}>{L.parentNameLabel}
              <input style={inputStyle} value={form.childName} onChange={(e) => setForm({ ...form, childName: e.target.value })} />
            </label>
          )}
          {form.person === "enfant" && (
            <label style={labelStyle}>{L.childName}
              {registeredKids && registeredKids.length > 0 && (
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
                  {registeredKids.map((ch) => (
                    <button key={ch.id} type="button" onClick={() => setForm({ ...form, childName: ch.name })} style={{
                      padding: "6px 13px", borderRadius: 999, fontSize: 12.5, fontWeight: 700, cursor: "pointer",
                      border: `1px solid ${form.childName === ch.name ? COLORS.teal : COLORS.line}`,
                      background: form.childName === ch.name ? COLORS.teal : "#fff",
                      color: form.childName === ch.name ? "#fff" : COLORS.text,
                    }}>{ch.name}</button>
                  ))}
                </div>
              )}
              <input style={inputStyle} value={form.childName} onChange={(e) => setForm({ ...form, childName: e.target.value })} />
            </label>
          )}
          <label style={labelStyle}>{L.appTitle}
            <input style={inputStyle} placeholder={L.appTitlePh} value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} />
          </label>
          <div style={{ display: "flex", gap: 10 }}>
            <label style={{ ...labelStyle, flex: 1 }}>{L.date}
              <input type="date" style={inputStyle} value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
            </label>
            <label style={{ ...labelStyle, flex: 1 }}>{L.time}
              <TimeSelect value={form.time} onChange={(t) => setForm({ ...form, time: t })} />
            </label>
          </div>
          <label style={labelStyle}>{L.location}
            <input style={inputStyle} value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} />
          </label>
          <label style={labelStyle}>{L.notes}
            <input style={inputStyle} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} />
          </label>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={addAppointment} disabled={saving} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "10px 20px", borderRadius: 10, fontWeight: 700, fontSize: 14, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1 }}>{saving ? "…" : L.save}</button>
            <button onClick={() => setShowForm(false)} style={{ background: "transparent", color: COLORS.muted, border: `1px solid ${COLORS.line}`, padding: "10px 20px", borderRadius: 10, fontWeight: 600, fontSize: 14, cursor: "pointer" }}>{L.cancel}</button>
          </div>
          {errorMsg && <p style={{ fontSize: 11.5, color: "#B3261E", marginTop: 10, marginBottom: 0 }}>{errorMsg}</p>}
        </Card>
      )}

      {appointments.length === 0 ? (
        <div style={{ opacity: 0.6 }}>
          <p style={{ fontSize: 11, fontWeight: 700, color: COLORS.muted, textAlign: "center", marginBottom: 8, fontStyle: "italic" }}>{L.exampleLabel}</p>
          <div style={{ border: `1px dashed ${COLORS.blue}80`, borderRadius: 14, padding: 2 }}>
            <AppointmentCard appt={EXAMPLE_APPT} hideRemove />
          </div>
          <p style={{ fontSize: 13, color: COLORS.muted, textAlign: "center", marginTop: 14, fontStyle: "italic" }}>{L.empty}</p>
        </div>
      ) : (
        <>
          {upcoming.length > 0 && (
            <div style={{ marginBottom: 20 }}>
              <p style={{ fontSize: 11.5, fontWeight: 800, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.03em", margin: "0 0 10px" }}>{L.upcoming}</p>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {upcoming.map((a) => <AppointmentCard key={a.id} appt={a} />)}
              </div>
            </div>
          )}
          {past.length > 0 && (
            <div>
              <p style={{ fontSize: 11.5, fontWeight: 800, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.03em", margin: "0 0 10px" }}>{L.past}</p>
              <DateGroupedList
                items={past}
                getDate={(a) => new Date(a.date + "T00:00:00")}
                getId={(a) => a.id}
                emptyLabel={L.empty}
                countLabel={(n) => `${n} ${L.apptsWord}`}
                loaded={loaded}
                lang={lang}
                renderItem={(a) => <AppointmentCard key={a.id} appt={a} faded />}
              />
            </div>
          )}
        </>
      )}
    </div>
  );
}

