function ResetPasswordScreen({ lang, session, onDone }) {
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [done, setDone] = useState(false);

  const L = lang === "fr"
    ? {
        title: "Choisissez un nouveau mot de passe", subtitle: "Ce mot de passe remplacera l'ancien pour votre compte.",
        password: "Nouveau mot de passe", confirm: "Confirmez le mot de passe", submit: "Enregistrer le nouveau mot de passe",
        mismatch: "Les deux mots de passe ne correspondent pas.", tooShort: "Le mot de passe doit contenir au moins 6 caractères.",
        doneTitle: "Mot de passe mis à jour !", doneText: "Vous pouvez maintenant continuer vers l'application.", continueBtn: "Continuer",
      }
    : lang === "es"
    ? {
        title: "Elige una nueva contraseña", subtitle: "Esta contraseña reemplazará la anterior de tu cuenta.",
        password: "Nueva contraseña", confirm: "Confirma la contraseña", submit: "Guardar la nueva contraseña",
        mismatch: "Las contraseñas no coinciden.", tooShort: "La contraseña debe tener al menos 6 caracteres.",
        doneTitle: "¡Contraseña actualizada!", doneText: "Ahora puedes continuar hacia la aplicación.", continueBtn: "Continuar",
      }
    : {
        title: "Choose a new password", subtitle: "This password will replace the old one for your account.",
        password: "New password", confirm: "Confirm password", submit: "Save new password",
        mismatch: "The two passwords don't match.", tooShort: "The password must be at least 6 characters long.",
        doneTitle: "Password updated!", doneText: "You can now continue to the app.", continueBtn: "Continue",
      };

  const submit = async () => {
    setErrorMsg("");
    if (password.length < 6) { setErrorMsg(L.tooShort); return; }
    if (password !== confirm) { setErrorMsg(L.mismatch); return; }
    setLoading(true);
    try {
      await supabaseUpdatePassword(password, session.access_token);
      setDone(true);
    } catch (err) {
      setErrorMsg(err.message);
    }
    setLoading(false);
  };

  const inputStyle = { width: "100%", padding: "12px 14px", borderRadius: 12, border: `1px solid ${COLORS.line}`, fontSize: 14.5, boxSizing: "border-box" };
  const labelStyle = { display: "block", fontSize: 13, fontWeight: 700, color: COLORS.text, marginBottom: 16 };

  return (
    <div style={{ fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh", padding: "24px 16px", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ maxWidth: 420, width: "100%", background: "#fff", borderRadius: 20, padding: "30px 26px", boxShadow: "0 4px 20px rgba(47,72,88,0.08)" }}>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}><Logo height={30} /></div>
        {done ? (
          <div style={{ textAlign: "center" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>✅</div>
            <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 8px" }}>{L.doneTitle}</h2>
            <p style={{ color: COLORS.muted, fontSize: 13.5, margin: "0 0 22px" }}>{L.doneText}</p>
            <button onClick={onDone} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "12px 26px", borderRadius: 999, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{L.continueBtn}</button>
          </div>
        ) : (
          <>
            <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 4px", textAlign: "center" }}>{L.title}</h2>
            <p style={{ color: COLORS.muted, fontSize: 13, textAlign: "center", margin: "0 0 20px" }}>{L.subtitle}</p>
            <label style={labelStyle}>{L.password}
              <input type="password" style={inputStyle} value={password} onChange={(e) => setPassword(e.target.value)} />
            </label>
            <label style={labelStyle}>{L.confirm}
              <input type="password" style={inputStyle} value={confirm} onChange={(e) => setConfirm(e.target.value)} />
            </label>
            {errorMsg && <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>}
            <button
              disabled={loading} onClick={submit}
              style={{
                width: "100%", background: COLORS.teal, color: "#fff", border: "none", padding: "13px",
                borderRadius: 12, fontSize: 15, fontWeight: 700, cursor: loading ? "default" : "pointer", opacity: loading ? 0.7 : 1,
              }}
            >{loading ? "…" : L.submit}</button>
          </>
        )}
      </div>
    </div>
  );
}

function PartnerSharing({ lang, session, userProfile, ownerLink, setOwnerLink, partnerLink, setPartnerLink, isMember, goTo }) {
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [codeInput, setCodeInput] = useState("");
  const [confirmRevoke, setConfirmRevoke] = useState(false);

  const L = lang === "fr"
    ? {
        title: "Partager mon compte", subtitle: "Invitez votre partenaire à consulter vos données (rendez-vous, tâches, suivis, documents, croissance) en lecture seule. Il ou elle ne pourra rien modifier — sauf dans l'outil « Idées de prénoms », où il ou elle pourra ajouter ses propres suggestions. Il ou elle n'aura jamais accès à votre abonnement ni à vos informations de paiement. Limité à une seule personne à la fois.",
        generate: "Générer une invitation", codeLabel: "Code d'invitation", sendEmail: "📧 Envoyer par courriel",
        emailPh: "Courriel de votre partenaire (optionnel, pour personnaliser le message)",
        cancelInvite: "Annuler l'invitation", pendingNote: "En attente — votre partenaire n'a pas encore entré ce code.",
        sharedWith: "Vous partagez votre compte en lecture seule.", revoke: "Retirer l'accès",
        revokeConfirm: "Retirer l'accès de votre partenaire ? Il ou elle ne pourra plus consulter vos données.",
        confirmBtn: "Oui, retirer", cancelBtn: "Annuler",
        joinTitle: "J'ai reçu un code d'invitation", joinSubtitle: "Entrez le code reçu pour consulter les données de votre partenaire (rendez-vous, tâches, suivis, documents, croissance) en lecture seule.",
        codeInputPh: "Ex. AB3D9F2K", join: "Rejoindre", alreadyPartner: (name) => `Vous consultez actuellement le compte de ${name || "votre partenaire"} en lecture seule.`,
        leaveLink: "Quitter ce partage",
        errInvalid: "Ce code n'est pas valide ou a déjà été utilisé.", errOwn: "Vous ne pouvez pas utiliser votre propre code.",
        emailSubject: "Invitation à consulter mes données sur Me My Baby",
        emailBody: (code, name) => `Bonjour,\n\n${name ? name + " vous invite" : "Vous êtes invité·e"} à consulter en lecture seule ses données de suivi de bébé sur l'application Me My Baby (rendez-vous, tâches familiales, allaitement, sommeil, couches, croissance, documents).\n\nVous ne pourrez rien modifier ni supprimer, à une seule exception : l'outil « Idées de prénoms », où vous pourrez ajouter vos propres suggestions de prénoms. Partout ailleurs, c'est un accès pour consulter seulement. Vous n'aurez jamais accès aux informations de paiement ou d'abonnement.\n\n📱 Accédez à l'application ici : ${APP_URL}\n\nPour vous connecter :\n1. Ouvrez le lien ci-dessus, puis créez votre propre compte gratuit (votre propre courriel et mot de passe).\n2. Une fois connecté·e, allez dans votre profil, section « J'ai reçu un code d'invitation ».\n3. Entrez ce code : ${code}\n\nÀ bientôt !`,
      }
    : lang === "es"
    ? {
        title: "Compartir mi cuenta", subtitle: "Invita a tu pareja a consultar tus datos (citas, tareas, seguimientos, documentos, crecimiento) en modo de solo lectura. No podrá modificar nada — excepto en la herramienta «Ideas de nombres», donde podrá agregar sus propias sugerencias. Nunca tendrá acceso a tu suscripción ni a tu información de pago. Limitado a una sola persona a la vez.",
        generate: "Generar una invitación", codeLabel: "Código de invitación", sendEmail: "📧 Enviar por correo",
        emailPh: "Correo de tu pareja (opcional, para personalizar el mensaje)",
        cancelInvite: "Cancelar la invitación", pendingNote: "Pendiente — tu pareja aún no ha ingresado este código.",
        sharedWith: "Estás compartiendo tu cuenta en modo de solo lectura.", revoke: "Retirar el acceso",
        revokeConfirm: "¿Retirar el acceso de tu pareja? Ya no podrá consultar tus datos.",
        confirmBtn: "Sí, retirar", cancelBtn: "Cancelar",
        joinTitle: "Recibí un código de invitación", joinSubtitle: "Ingresa el código recibido para consultar los datos de tu pareja (citas, tareas, seguimientos, documentos, crecimiento) en modo de solo lectura.",
        codeInputPh: "Ej. AB3D9F2K", join: "Unirme", alreadyPartner: (name) => `Actualmente estás consultando la cuenta de ${name || "tu pareja"} en modo de solo lectura.`,
        leaveLink: "Salir de este acceso compartido",
        errInvalid: "Este código no es válido o ya fue usado.", errOwn: "No puedes usar tu propio código.",
        emailSubject: "Invitación para consultar mis datos en Me My Baby",
        emailBody: (code, name) => `Hola,\n\n${name ? name + " te invita" : "Estás invitado/a"} a consultar en modo de solo lectura sus datos de seguimiento del bebé en la aplicación Me My Baby (citas, tareas familiares, lactancia, sueño, pañales, crecimiento, documentos).\n\nNo podrás modificar ni eliminar nada, con una sola excepción: la herramienta «Ideas de nombres», donde podrás agregar tus propias sugerencias de nombres. En todo lo demás, es un acceso solo para consultar. Nunca tendrás acceso a la información de pago o suscripción.\n\n📱 Accede a la aplicación aquí: ${APP_URL}\n\nPara conectarte:\n1. Abre el enlace de arriba, luego crea tu propia cuenta gratuita (tu propio correo y contraseña).\n2. Una vez conectado/a, ve a tu perfil, sección «Recibí un código de invitación».\n3. Ingresa este código: ${code}\n\n¡Hasta pronto!`,
      }
    : {
        title: "Share my account", subtitle: "Invite your partner to view your data (appointments, tasks, tracking, documents, growth) in read-only mode. They won't be able to change anything — except in the \"Baby name ideas\" tool, where they can add their own suggestions. They will never have access to your subscription or payment information. Limited to one person at a time.",
        generate: "Generate an invite", codeLabel: "Invite code", sendEmail: "📧 Send by email",
        emailPh: "Your partner's email (optional, to personalize the message)",
        cancelInvite: "Cancel the invite", pendingNote: "Pending — your partner hasn't entered this code yet.",
        sharedWith: "You're sharing your account in read-only mode.", revoke: "Remove access",
        revokeConfirm: "Remove your partner's access? They'll no longer be able to view your data.",
        confirmBtn: "Yes, remove", cancelBtn: "Cancel",
        joinTitle: "I received an invite code", joinSubtitle: "Enter the code you received to view your partner's data (appointments, tasks, tracking, documents, growth) in read-only mode.",
        codeInputPh: "E.g. AB3D9F2K", join: "Join", alreadyPartner: (name) => `You're currently viewing ${name || "your partner"}'s account in read-only mode.`,
        leaveLink: "Leave this shared access",
        errInvalid: "This code isn't valid or has already been used.", errOwn: "You can't use your own code.",
        emailSubject: "Invitation to view my data on Me My Baby",
        emailBody: (code, name) => `Hi,\n\n${name ? name + " is inviting you" : "You're invited"} to view, in read-only mode, their baby tracking data on the Me My Baby app (appointments, family tasks, feeding, sleep, diapers, growth, documents).\n\nYou won't be able to change or delete anything, with one exception: the "Baby name ideas" tool, where you can add your own name suggestions. Everywhere else, it's view-only access. You'll never have access to payment or subscription information.\n\n📱 Access the app here: ${APP_URL}\n\nTo connect:\n1. Open the link above, then create your own free account (your own email and password).\n2. Once logged in, go to your profile, "I received an invite code" section.\n3. Enter this code: ${code}\n\nSee you soon!`,
      };

  const hasSession = !!(session?.access_token && session?.user?.id);

  const createInvite = async () => {
    setErrorMsg(""); setLoading(true);
    try {
      const link = await supabaseCreatePartnerInvite(session.user.id, session.access_token);
      setOwnerLink(link);
    } catch (err) { setErrorMsg(err.message); }
    setLoading(false);
  };
  const revokeInvite = async () => {
    setErrorMsg(""); setLoading(true);
    try {
      await supabaseRevokePartnerLink(ownerLink.id, session.access_token);
      setOwnerLink(null);
      setConfirmRevoke(false);
    } catch (err) { setErrorMsg(err.message); }
    setLoading(false);
  };
  const sendInviteEmail = () => {
    const body = L.emailBody(ownerLink.invite_code, userProfile?.firstName);
    window.open(`mailto:?subject=${encodeURIComponent(L.emailSubject)}&body=${encodeURIComponent(body)}`, "_blank");
  };
  const joinWithCode = async () => {
    if (!codeInput.trim()) return;
    setErrorMsg(""); setLoading(true);
    try {
      const link = await supabaseRedeemInviteCode(codeInput.trim().toUpperCase(), session.user.id, session.access_token);
      setPartnerLink(link);
      setCodeInput("");
    } catch (err) {
      setErrorMsg(err.message === "CODE_INVALIDE" ? L.errInvalid : err.message === "CODE_PROPRE_COMPTE" ? L.errOwn : err.message);
    }
    setLoading(false);
  };
  const leaveShare = async () => {
    setErrorMsg(""); setLoading(true);
    try {
      await supabaseRevokePartnerLink(partnerLink.id, session.access_token);
      setPartnerLink(null);
    } catch (err) { setErrorMsg(err.message); }
    setLoading(false);
  };

  if (!hasSession) return null;

  return (
    <Card>
      <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 17, color: COLORS.teal }}>{L.title}</h3>
      <p style={{ margin: "0 0 16px", fontSize: 12.5, color: COLORS.muted, lineHeight: 1.55 }}>{L.subtitle}</p>

      {partnerLink ? (
        <div style={{ background: "#F0F5EC", borderRadius: 12, padding: "12px 14px", marginBottom: 18 }}>
          <p style={{ margin: "0 0 10px", fontSize: 13, color: COLORS.text, fontWeight: 600 }}>👁️ {L.alreadyPartner(userProfile?.firstName)}</p>
          <button onClick={leaveShare} disabled={loading} style={{ background: "none", border: "none", color: "#B3261E", fontSize: 12.5, fontWeight: 700, cursor: "pointer", padding: 0, textDecoration: "underline" }}>{L.leaveLink}</button>
        </div>
      ) : ownerLink ? (
        <div style={{ background: ownerLink.status === "accepted" ? "#F0F5EC" : COLORS.cream, borderRadius: 12, padding: "14px 16px", marginBottom: 18 }}>
          {ownerLink.status === "accepted" ? (
            <p style={{ margin: "0 0 10px", fontSize: 13, color: COLORS.text, fontWeight: 600 }}>✅ {L.sharedWith}</p>
          ) : (
            <>
              <p style={{ margin: "0 0 4px", fontSize: 11, fontWeight: 700, color: COLORS.muted, textTransform: "uppercase" }}>{L.codeLabel}</p>
              <p style={{ margin: "0 0 10px", fontSize: 22, fontWeight: 800, color: COLORS.teal, letterSpacing: 2 }}>{ownerLink.invite_code}</p>
              <button onClick={sendInviteEmail} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "9px 16px", borderRadius: 999, fontWeight: 700, fontSize: 12.5, cursor: "pointer", marginBottom: 10 }}>{L.sendEmail}</button>
              <p style={{ margin: "0 0 10px", fontSize: 11.5, color: COLORS.muted, fontStyle: "italic" }}>{L.pendingNote}</p>
            </>
          )}
          <div>
            <button onClick={() => setConfirmRevoke(true)} disabled={loading} style={{ background: "none", border: "none", color: "#B3261E", fontSize: 12.5, fontWeight: 700, cursor: "pointer", padding: 0, textDecoration: "underline" }}>
              {ownerLink.status === "accepted" ? L.revoke : L.cancelInvite}
            </button>
          </div>
        </div>
      ) : isMember ? (
        <button onClick={createInvite} disabled={loading} style={{
          width: "100%", padding: "12px", borderRadius: 12, border: "none", background: COLORS.teal, color: "#fff",
          fontWeight: 700, fontSize: 13.5, cursor: loading ? "default" : "pointer", opacity: loading ? 0.7 : 1, marginBottom: 22,
        }}>{loading ? "…" : L.generate}</button>
      ) : (
        <div style={{ marginBottom: 22 }}>
          <LockedContent lang={lang} goTo={goTo} />
        </div>
      )}

      {errorMsg && <p style={{ fontSize: 11.5, color: "#B3261E", marginBottom: 14 }}>{errorMsg}</p>}

      {confirmRevoke && (
        <div onClick={() => setConfirmRevoke(false)} style={{
          position: "fixed", inset: 0, zIndex: 300, background: "rgba(47,72,88,0.5)",
          display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
        }}>
          <div onClick={(ev) => ev.stopPropagation()} style={{ background: "#fff", borderRadius: 20, maxWidth: 380, width: "100%", padding: "26px 24px", textAlign: "center", boxShadow: "0 20px 50px rgba(0,0,0,0.3)" }}>
            <p style={{ fontSize: 14, color: COLORS.text, lineHeight: 1.55, margin: "0 0 22px" }}>{L.revokeConfirm}</p>
            <div style={{ display: "flex", gap: 10, justifyContent: "center" }}>
              <button onClick={() => setConfirmRevoke(false)} style={{ background: "none", border: `1px solid ${COLORS.line}`, color: COLORS.muted, padding: "10px 20px", borderRadius: 999, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{L.cancelBtn}</button>
              <button onClick={revokeInvite} style={{ background: "#B3261E", color: "#fff", border: "none", padding: "10px 20px", borderRadius: 999, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{L.confirmBtn}</button>
            </div>
          </div>
        </div>
      )}

      {!ownerLink && !partnerLink && (
        <div style={{ borderTop: `1px solid ${COLORS.line}`, paddingTop: 18 }}>
          <p style={{ margin: "0 0 4px", fontSize: 13.5, fontWeight: 700, color: COLORS.text }}>{L.joinTitle}</p>
          <p style={{ margin: "0 0 12px", fontSize: 12, color: COLORS.muted, lineHeight: 1.5 }}>{L.joinSubtitle}</p>
          <div style={{ display: "flex", gap: 8 }}>
            <input
              value={codeInput} onChange={(e) => setCodeInput(e.target.value)} placeholder={L.codeInputPh}
              style={{ flex: 1, padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14, letterSpacing: 1, textTransform: "uppercase", boxSizing: "border-box" }}
            />
            <button onClick={joinWithCode} disabled={loading} style={{ padding: "10px 18px", borderRadius: 10, border: "none", background: COLORS.ochre, color: "#fff", fontWeight: 700, fontSize: 13, cursor: loading ? "default" : "pointer" }}>{loading ? "…" : L.join}</button>
          </div>
        </div>
      )}
    </Card>
  );
}

function ProfileGate({ lang, onComplete }) {
  const [mode, setMode] = useState("signup"); // "signup" | "login"
  const [step, setStep] = useState("form"); // "form" | "verify" | "forgot" | "forgotSent"
  const [forgotEmail, setForgotEmail] = useState("");
  const [form, setForm] = useState({ firstName: "", lastName: "", email: "", password: "" });
  const [loginForm, setLoginForm] = useState({ email: "", password: "" });
  const [resendMsg, setResendMsg] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [legalDoc, setLegalDoc] = useState(null); // "privacy" | "terms" | null

  const handleSubmit = async () => {
    if (!(form.firstName.trim() && form.email.trim() && form.password.length >= 8 && acceptedTerms)) return;
    setLoading(true);
    setErrorMsg("");

    try {
      const result = await supabaseSignUp(form.email.trim(), form.password, {
        first_name: form.firstName.trim(),
        last_name: form.lastName.trim(),
      });

      setLoading(false);
      if (result?.access_token) {
        // On enregistre la preuve de consentement (date + heure) ET la langue choisie au moment de
        // l'inscription (le sélecteur de langue en haut de l'écran est déjà disponible ici) — sans ça,
        // le profil retombait toujours sur le français par défaut à la prochaine connexion, peu importe
        // la langue choisie pendant l'inscription.
        try {
          await supabaseUpdateProfile(result.user.id, {
            terms_accepted: true, terms_accepted_at: new Date().toISOString(), language: lang,
          }, result.access_token);
        } catch (e) { /* n'empêche pas la création du compte si cette mise à jour échoue */ }
        // La confirmation par courriel n'est pas activée côté Supabase : on entre directement.
        onComplete(form, result, true);
      } else {
        // Un code à 6 chiffres vient d'être envoyé par courriel.
        setStep("verify");
      }
    } catch (err) {
      setErrorMsg(err.message === "EMAIL_ALREADY_REGISTERED" ? L.emailExists : err.message);
      setLoading(false);
    }
  };

  const handleResend = async () => {
    setErrorMsg("");
    setResendMsg("");
    try {
      await supabaseResendOtp(form.email.trim(), "signup");
      setResendMsg(lang === "fr" ? "Le courriel a été renvoyé." : lang === "es" ? "El correo fue reenviado." : "The email has been resent.");
    } catch (err) {
      setErrorMsg(err.message);
    }
  };

  const handleLogin = async () => {
    if (!(loginForm.email.trim() && loginForm.password)) return;
    setLoading(true);
    setErrorMsg("");
    try {
      const session = await supabaseSignIn(loginForm.email.trim(), loginForm.password);
      setLoading(false);
      onComplete(null, session, false);
    } catch (err) {
      setErrorMsg(err.message);
      setLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!forgotEmail.trim()) return;
    setLoading(true);
    setErrorMsg("");
    try {
      await supabaseRequestPasswordReset(forgotEmail.trim(), window.location.origin + window.location.pathname);
      setStep("forgotSent");
    } catch (err) {
      setErrorMsg(err.message);
    }
    setLoading(false);
  };

  const L = lang === "fr"
    ? {
        title: "Bienvenue dans Me My Baby", subtitle: "Créez votre compte gratuit pour commencer à explorer l'application.",
        firstName: "Nom", email: "Courriel", password: "Mot de passe", passwordHint: "8 caractères minimum",
        submit: "Créer mon compte gratuit",
        note: "La création d'un compte est requise pour utiliser l'application. Vous pourrez ensuite explorer librement — le contenu détaillé est réservé aux membres.",
        acceptTermsPrefix: "J'accepte les ", termsLabel: "conditions d'utilisation", acceptTermsMiddle: " et la ", privacyLabel: "politique de confidentialité",
        acceptTermsRequired: "Vous devez accepter les conditions d'utilisation et la politique de confidentialité pour créer un compte.",
        emailExists: "Ce courriel existe déjà dans notre base de données. Veuillez vous connecter ou utiliser une autre adresse.",
        medicalReminder: "⚠️ Le contenu de l'application est informatif et ne remplace pas l'avis d'un professionnel de la santé.",
        loginTitle: "Content de vous revoir", loginSubtitle: "Connectez-vous pour retrouver votre profil.",
        loginSubmit: "Se connecter", switchToLogin: "Déjà membre ? Se connecter",
        forgotLink: "Mot de passe oublié ?", forgotTitle: "Mot de passe oublié", forgotSubtitle: "Entrez votre courriel — on vous enverra un lien pour en choisir un nouveau.",
        forgotSubmit: "Envoyer le lien", backToLogin: "← Retour à la connexion",
        forgotSentTitle: "Courriel envoyé !", forgotSentText: "Si un compte existe avec cette adresse, un lien pour réinitialiser votre mot de passe vient d'être envoyé. Vérifiez aussi vos courriels indésirables.",
        switchToSignup: "Pas encore de compte ? Créer un profil",
        verifyTitle: "Vérifiez votre courriel",
        verifySubtitle: (email) => `Nous avons envoyé un courriel de confirmation à ${email}. Cliquez sur le lien qu'il contient pour activer votre compte — vous serez automatiquement dirigé·e vers l'application.`,
        resend: "Renvoyer le courriel", changeEmail: "Modifier mon courriel",
      }
    : lang === "es"
    ? {
        title: "Bienvenida a Me My Baby", subtitle: "Crea tu cuenta gratuita para empezar a explorar la aplicación.",
        firstName: "Nombre", email: "Correo electrónico", password: "Contraseña", passwordHint: "Mínimo 8 caracteres",
        submit: "Crear mi cuenta gratuita",
        note: "Se requiere crear una cuenta para usar la aplicación. Después podrás explorar libremente — el contenido detallado está reservado para miembros.",
        acceptTermsPrefix: "Acepto los ", termsLabel: "términos de uso", acceptTermsMiddle: " y la ", privacyLabel: "política de privacidad",
        acceptTermsRequired: "Debes aceptar los términos de uso y la política de privacidad para crear una cuenta.",
        emailExists: "Este correo ya existe en nuestra base de datos. Inicia sesión o usa otra dirección.",
        medicalReminder: "⚠️ El contenido de la aplicación es informativo y no sustituye el consejo de un profesional de la salud.",
        designerSkip: "Vista previa de diseñadora — acceso completo, sin crear perfil",
        loginTitle: "Qué bueno verte de nuevo", loginSubtitle: "Inicia sesión para recuperar tu perfil.",
        loginSubmit: "Iniciar sesión", switchToLogin: "¿Ya eres miembro? Inicia sesión",
        forgotLink: "¿Olvidaste tu contraseña?", forgotTitle: "Contraseña olvidada", forgotSubtitle: "Ingresa tu correo — te enviaremos un enlace para elegir una nueva.",
        forgotSubmit: "Enviar el enlace", backToLogin: "← Volver a iniciar sesión",
        forgotSentTitle: "¡Correo enviado!", forgotSentText: "Si existe una cuenta con esta dirección, se acaba de enviar un enlace para restablecer tu contraseña. Revisa también tu carpeta de correo no deseado.",
        switchToSignup: "¿Aún no tienes cuenta? Crea un perfil",
        verifyTitle: "Verifica tu correo electrónico",
        verifySubtitle: (email) => `Enviamos un correo de confirmación a ${email}. Haz clic en el enlace que contiene para activar tu cuenta — serás dirigido automáticamente a la aplicación.`,
        resend: "Reenviar el correo", changeEmail: "Cambiar mi correo",
      }
    : {
        title: "Welcome to Me My Baby", subtitle: "Create your free account to start exploring the app.",
        firstName: "Name", email: "Email", password: "Password", passwordHint: "8 characters minimum",
        submit: "Create my free account",
        note: "Creating an account is required to use the app. After that you can browse freely — detailed content is reserved for members.",
        acceptTermsPrefix: "I agree to the ", termsLabel: "Terms of Use", acceptTermsMiddle: " and ", privacyLabel: "Privacy Policy",
        acceptTermsRequired: "You must agree to the Terms of Use and Privacy Policy to create an account.",
        emailExists: "This email already exists in our database. Please log in or use a different address.",
        medicalReminder: "⚠️ The app's content is informational and does not replace advice from a healthcare professional.",
        designerSkip: "Designer preview — full access, no profile needed",
        loginTitle: "Good to see you again", loginSubtitle: "Log in to pick up right where you left off.",
        loginSubmit: "Log in", switchToLogin: "Already a member? Log in",
        forgotLink: "Forgot password?", forgotTitle: "Forgot password", forgotSubtitle: "Enter your email — we'll send you a link to choose a new one.",
        forgotSubmit: "Send the link", backToLogin: "← Back to login",
        forgotSentTitle: "Email sent!", forgotSentText: "If an account exists with this address, a password reset link was just sent. Check your spam folder too.",
        switchToSignup: "No account yet? Create a profile",
        verifyTitle: "Verify your email",
        verifySubtitle: (email) => `We sent a confirmation email to ${email}. Click the link inside it to activate your account — you'll be taken straight into the app.`,
        resend: "Resend email", changeEmail: "Change my email",
      };

  const inputStyle = { width: "100%", padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14.5, boxSizing: "border-box", fontFamily: "inherit" };
  const labelStyle = { display: "flex", flexDirection: "column", gap: 6, fontSize: 13.5, color: COLORS.muted, fontWeight: 600, marginBottom: 14 };

  return (
    <div style={{
      fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh",
      display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
    }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap'); * { box-sizing: border-box; }`}</style>
      <div style={{ width: "100%", maxWidth: 440 }}>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
          <Logo height={36} />
        </div>
        <Card>
          {step === "forgot" ? (
            <div>
              <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 4px", textAlign: "center" }}>{L.forgotTitle}</h2>
              <p style={{ color: COLORS.muted, fontSize: 13, textAlign: "center", margin: "0 0 20px" }}>{L.forgotSubtitle}</p>
              <label style={labelStyle}>{L.email}
                <input required type="email" style={inputStyle} value={forgotEmail} onChange={(e) => setForgotEmail(e.target.value)} />
              </label>
              {errorMsg && <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>}
              <button
                type="button" disabled={loading} onClick={handleForgotPassword}
                style={{
                  width: "100%", background: COLORS.teal, color: "#fff", border: "none", padding: "13px",
                  borderRadius: 12, fontSize: 15, fontWeight: 700, cursor: loading ? "default" : "pointer", opacity: loading ? 0.7 : 1, marginBottom: 14,
                }}>{loading ? "…" : L.forgotSubmit}</button>
              <div style={{ textAlign: "center" }}>
                <button onClick={() => { setStep("form"); setErrorMsg(""); }} style={{ background: "none", border: "none", color: COLORS.muted, fontSize: 12.5, textDecoration: "underline", cursor: "pointer" }}>{L.backToLogin}</button>
              </div>
            </div>
          ) : step === "forgotSent" ? (
            <div style={{ textAlign: "center" }}>
              <div style={{
                width: 64, height: 64, borderRadius: "50%", background: "#EAF2F8", display: "flex",
                alignItems: "center", justifyContent: "center", margin: "0 auto 16px",
              }}>
                <Mail size={28} color={COLORS.blue} />
              </div>
              <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 8px" }}>{L.forgotSentTitle}</h2>
              <p style={{ color: COLORS.muted, fontSize: 13.5, margin: "0 0 20px", lineHeight: 1.5 }}>{L.forgotSentText}</p>
              <button onClick={() => { setStep("form"); setMode("login"); setErrorMsg(""); }} style={{ background: "none", border: "none", color: COLORS.teal, fontSize: 12.5, fontWeight: 700, textDecoration: "underline", cursor: "pointer" }}>{L.backToLogin}</button>
            </div>
          ) : step === "verify" ? (
            <div style={{ textAlign: "center" }}>
              <div style={{
                width: 64, height: 64, borderRadius: "50%", background: "#EAF2F8", display: "flex",
                alignItems: "center", justifyContent: "center", margin: "0 auto 16px",
              }}>
                <Mail size={28} color={COLORS.blue} />
              </div>
              <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 22, color: COLORS.teal, margin: "0 0 8px" }}>{L.verifyTitle}</h2>
              <p style={{ color: COLORS.muted, fontSize: 13.5, margin: "0 0 20px", lineHeight: 1.5 }}>{L.verifySubtitle(form.email.trim())}</p>
              {errorMsg && (
                <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>
              )}
              {resendMsg && (
                <p style={{ color: COLORS.sage, fontSize: 13, marginBottom: 12, fontWeight: 600 }}>{resendMsg}</p>
              )}
              <div style={{ display: "flex", justifyContent: "center", gap: 18 }}>
                <button onClick={handleResend} style={{ background: "none", border: "none", color: COLORS.teal, fontSize: 12.5, fontWeight: 700, textDecoration: "underline", cursor: "pointer" }}>{L.resend}</button>
                <button onClick={() => { setStep("form"); setErrorMsg(""); setResendMsg(""); }} style={{ background: "none", border: "none", color: COLORS.muted, fontSize: 12.5, textDecoration: "underline", cursor: "pointer" }}>{L.changeEmail}</button>
              </div>
            </div>
          ) : (
          <>
          <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 22, color: COLORS.teal, margin: "0 0 4px", textAlign: "center" }}>{mode === "login" ? L.loginTitle : L.title}</h2>
          <p style={{ color: COLORS.muted, fontSize: 13.5, textAlign: "center", margin: "0 0 20px" }}>{mode === "login" ? L.loginSubtitle : L.subtitle}</p>

          {mode === "login" ? (
            <div>
              <label style={labelStyle}>{L.email}
                <input required type="email" style={inputStyle} value={loginForm.email} onChange={(e) => setLoginForm({ ...loginForm, email: e.target.value })} />
              </label>
              <label style={labelStyle}>{L.password}
                <input required type="password" style={inputStyle} value={loginForm.password} onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })} />
              </label>
              <div style={{ textAlign: "right", marginBottom: 12, marginTop: -8 }}>
                <button type="button" onClick={() => { setStep("forgot"); setForgotEmail(loginForm.email); setErrorMsg(""); }} style={{ background: "none", border: "none", color: COLORS.blue, fontSize: 12, fontWeight: 600, textDecoration: "underline", cursor: "pointer", padding: 0 }}>{L.forgotLink}</button>
              </div>
              {errorMsg && (
                <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>
              )}
              <button
                type="button"
                disabled={loading}
                onClick={handleLogin}
                style={{
                  width: "100%", background: COLORS.teal, color: "#fff", border: "none", padding: "13px",
                  borderRadius: 12, fontSize: 15, fontWeight: 700, cursor: loading ? "default" : "pointer",
                  opacity: loading ? 0.7 : 1,
                }}>{loading ? "..." : L.loginSubmit}</button>
            </div>
          ) : (
          <div>
            <label style={labelStyle}>{L.firstName}
              <input required style={inputStyle} value={form.firstName} onChange={(e) => setForm({ ...form, firstName: e.target.value })} />
            </label>
            <label style={labelStyle}>{L.email}
              <input required type="email" style={inputStyle} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
            </label>
            <label style={labelStyle}>{L.password}
              <input required type="password" minLength={8} style={inputStyle} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} />
              <span style={{ fontWeight: 400, fontSize: 11.5, color: COLORS.muted }}>{L.passwordHint}</span>
            </label>
            {errorMsg && (
              <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>
            )}
            <label style={{ display: "flex", alignItems: "flex-start", gap: 9, fontSize: 12.5, color: COLORS.muted, marginBottom: 14, cursor: "pointer", lineHeight: 1.5 }}>
              <input type="checkbox" checked={acceptedTerms} onChange={(e) => setAcceptedTerms(e.target.checked)} style={{ marginTop: 2, flexShrink: 0 }} />
              <span>
                {L.acceptTermsPrefix}
                <button type="button" onClick={(e) => { e.preventDefault(); setLegalDoc("terms"); }} style={{ background: "none", border: "none", padding: 0, color: COLORS.teal, textDecoration: "underline", cursor: "pointer", font: "inherit" }}>{L.termsLabel}</button>
                {L.acceptTermsMiddle}
                <button type="button" onClick={(e) => { e.preventDefault(); setLegalDoc("privacy"); }} style={{ background: "none", border: "none", padding: 0, color: COLORS.teal, textDecoration: "underline", cursor: "pointer", font: "inherit" }}>{L.privacyLabel}</button>
              </span>
            </label>
            <button
              type="button"
              disabled={loading || !acceptedTerms}
              onClick={handleSubmit}
              style={{
                width: "100%", background: COLORS.teal, color: "#fff", border: "none", padding: "13px",
                borderRadius: 12, fontSize: 15, fontWeight: 700, cursor: (loading || !acceptedTerms) ? "default" : "pointer",
                opacity: (loading || !acceptedTerms) ? 0.5 : 1,
              }}>{loading ? "..." : L.submit}</button>
          </div>
          )}
          </>
          )}
        </Card>
        {legalDoc && <LegalModal lang={lang} doc={legalDoc} onClose={() => setLegalDoc(null)} />}
        {step === "form" && mode === "signup" && (
          <>
            <p style={{
              fontSize: 11.5, color: COLORS.teal, textAlign: "center", marginTop: 14, lineHeight: 1.5,
              background: "#EAF2F8", borderRadius: 10, padding: "8px 12px", fontWeight: 600,
            }}>{L.medicalReminder}</p>
            <p style={{ fontSize: 12, color: COLORS.muted, textAlign: "center", marginTop: 10, lineHeight: 1.5 }}>{L.note}</p>
          </>
        )}
        {step === "form" && (
        <>
        <button
          onClick={() => { setMode(mode === "login" ? "signup" : "login"); setErrorMsg(""); }}
          style={{
            display: "block", margin: "16px auto 0", background: "none", border: "none",
            color: COLORS.teal, fontSize: 13, fontWeight: 700, textDecoration: "underline", cursor: "pointer",
          }}
        >
          {mode === "login" ? L.switchToSignup : L.switchToLogin}
        </button>
        </>
        )}
      </div>
    </div>
  );
}

// Alerte automatique par courriel en cas d'erreur JavaScript imprévue dans l'app — plafonnée à un envoi
// par type d'erreur par heure (via sessionStorage) pour éviter d'inonder ta boîte de courriel si la
// même erreur se répète en boucle.
function reportAppError(message, extra) {
  try {
    const key = `err-report-${message}`.slice(0, 100);
    const last = Number(sessionStorage.getItem(key) || 0);
    if (Date.now() - last < 60 * 60 * 1000) return; // déjà signalée dans la dernière heure
    sessionStorage.setItem(key, String(Date.now()));
  } catch { /* sessionStorage indisponible — on tente quand même l'envoi */ }
  const html = `<div style="font-family:Georgia,serif;color:#3A3833;max-width:560px;margin:0 auto;line-height:1.5;font-size:13px;">
    <p><strong>Erreur :</strong> ${String(message).slice(0, 500)}</p>
    <p><strong>Page :</strong> ${window.location?.href || ""}</p>
    <p><strong>Heure :</strong> ${new Date().toISOString()}</p>
    <p><strong>Navigateur :</strong> ${navigator.userAgent}</p>
    ${extra ? `<p><strong>Détail :</strong> ${String(extra).slice(0, 1000)}</p>` : ""}
  </div>`;
  sendAppEmail("Memybaby.app@gmail.com", "⚠️ Erreur détectée sur Me My Baby", html).catch(() => { /* si même le rapport d'erreur échoue, on abandonne silencieusement */ });
}

// Détecte la langue préférée du téléphone/navigateur au tout premier chargement (avant toute
// connexion) — utilisée seulement tant qu'aucune langue n'a été choisie ou sauvegardée dans un
// profil ; une fois connectée, la langue du profil ou un choix manuel prend toujours le dessus.
// Fonctionne aussi bien sur le web que dans une future version empaquetée pour l'App Store/Google
// Play (Capacitor), puisque navigator.language reflète la langue de l'appareil dans les deux cas.
function detectInitialLang() {
  if (typeof navigator === "undefined") return "fr";
  const candidates = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || "fr"];
  for (const l of candidates) {
    const base = String(l).toLowerCase().slice(0, 2);
    if (base === "es") return "es";
    if (base === "en") return "en";
    if (base === "fr") return "fr";
  }
  return "fr";
}

export default function App() {
  const [lang, setLang] = useState(detectInitialLang);
  const [active, setActive] = useState("accueil");
  const [navOpen, setNavOpen] = useState(false);
  const [hasProfile, setHasProfile] = useState(false);
  const [userProfile, setUserProfile] = useState(null);
  const [isMember, setIsMember] = useState(false);
  const [ownerLink, setOwnerLink] = useState(null); // invitation créée par CE compte pour inviter un·e partenaire
  const [partnerLink, setPartnerLink] = useState(null); // lien où CE compte est le/la partenaire (lecture seule du compte d'un·e autre)
  // L'accès au contenu réservé aux membres tient compte aussi du statut d'abonnement :
  // - un compte bloqué pour échec de paiement perd l'accès immédiatement, jusqu'à mise à jour du paiement.
  // - un abonnement annulé garde l'accès jusqu'à la fin de la période déjà payée (subscriptionAccessUntil),
  //   puis le perd automatiquement une fois cette date passée — sans qu'aucune action supplémentaire soit requise.
  // - un·e partenaire lié·e (partnerLink actif) a accès en lecture seule sans avoir besoin de son propre abonnement,
  //   puisque c'est le compte titulaire (maman) qui paie.
  const cancelledAndExpired = userProfile?.subscriptionStatus === "cancelled"
    && userProfile?.subscriptionAccessUntil
    && new Date(userProfile.subscriptionAccessUntil + "T23:59:59") < new Date();
  // isAdmin ne débloque PAS l'accès membre (le compte admin doit pouvoir tester le vrai cheminement
  // non-membre → abonnement → membre) — il sert uniquement à révéler, plus tard, des sections/outils
  // réservés à ce compte (gestion des promotions, codes, etc.), séparément du statut membre.
  const isAdmin = isAdminEmail(userProfile?.email);
  const isMemberActive = isMember && userProfile?.subscriptionStatus !== "payment_failed" && !cancelledAndExpired;
  // Quand on consulte le compte d'un·e partenaire : les appels aux données doivent cibler SON id à elle/lui
  // (le compte titulaire), pas le nôtre — et toute action d'ajout/modification/suppression doit rester bloquée.
  const isReadOnlyPartner = !!partnerLink;
  const [children, setChildren] = useState([]);
  const [activeChildId, setActiveChildId] = useState(null);
  const [session, setSession] = useState(null); // { access_token, refresh_token, user, isMember }
  const [justSignedUp, setJustSignedUp] = useState(false);
  const [justBecameMember, setJustBecameMember] = useState(false);
  const [checkingSession, setCheckingSession] = useState(true);
  const [needsPasswordReset, setNeedsPasswordReset] = useState(false);
  const effectiveUserId = partnerLink ? partnerLink.owner_user_id : session?.user?.id;
  // "Session miroir" : même jeton d'authentification (donc toute tentative d'écriture reste bloquée
  // côté base de données, puisque le jeton réel de papa ne correspond pas à l'id de maman), mais avec
  // l'id du compte titulaire pour que toutes les lectures de données pointent vers son compte à elle.
  const effectiveSession = (partnerLink && session) ? { ...session, user: { ...session.user, id: effectiveUserId } } : session;

  // Écoute globale des erreurs JavaScript imprévues (bug non géré, requête qui plante, etc.) pour
  // t'envoyer un courriel automatique — voir reportAppError plus haut.
  useEffect(() => {
    const onError = (event) => reportAppError(event.message || "Erreur inconnue", event.error?.stack);
    const onRejection = (event) => reportAppError("Promesse rejetée non gérée", String(event.reason));
    window.addEventListener("error", onError);
    window.addEventListener("unhandledrejection", onRejection);
    return () => {
      window.removeEventListener("error", onError);
      window.removeEventListener("unhandledrejection", onRejection);
    };
  }, []);

  const [pendingSubtab, setPendingSubtab] = useState(null); // sous-onglet précis à ouvrir dès l'arrivée sur une section

  // Pile de navigation : garde l'onglet précédent à chaque déplacement, pour permettre un vrai
  // bouton "Retour" partout dans l'app plutôt que de dépendre du bouton retour du navigateur.
  const [navStack, setNavStack] = useState([]);

  const goTo = (id, subtab) => {
    setNavStack((stack) => (active && active !== id ? [...stack, active] : stack));
    setActive(id);
    setPendingSubtab(subtab || null);
    setNavOpen(false);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const goBack = () => {
    setNavStack((stack) => {
      if (stack.length === 0) { setActive("accueil"); return stack; }
      const prev = stack[stack.length - 1];
      setActive(prev);
      setPendingSubtab(null);
      return stack.slice(0, -1);
    });
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const mapProfileRow = (row) => ({
    firstName: row.first_name || "", lastName: row.last_name || "", email: row.email || "",
    username: row.username || "", country: row.country || "", language: row.language || "fr",
    motherAge: row.mother_age || "", motherBirthdate: row.mother_birthdate || "", children: row.children ?? "0",
    childrenAgesArr: (row.children_ages || "").split(",").map((s) => s.trim()).filter(Boolean),
    dueDate: row.due_date || "", pregnancyProfile: row.pregnancy_profile || [], newsletter: row.newsletter ?? true,
    photoUrl: row.photo_url || null,
    birthAnnouncementPending: row.birth_announcement_pending || false,
    birthAnnouncementName: row.birth_announcement_name || "",
    billingCycle: row.billing_cycle || "monthly",
    billingAnchorDate: row.billing_anchor_date || "",
    subscriptionStatus: row.subscription_status || "active",
    subscriptionAccessUntil: row.subscription_access_until || "",
    lastMenuRequestAt: row.last_menu_request_at || "",
    preferredCurrency: row.preferred_currency || "",
  });

  // Détecte si la date prévue d'accouchement est maintenant dans le passé : dans ce cas, on considère
  // que bébé est né (l'enfant "à venir" est déjà compté comme un enfant actuel dès que sa date de
  // naissance est passée — voir le filtre utilisé partout ailleurs). On vide alors la DPA (le champ
  // redevient gris, comme non répondu) et on active un message de bienvenue à afficher une seule fois
  // à la prochaine visite de la page d'accueil.
  const checkDueDateTransition = async (sess, profile) => {
    if (!profile?.dueDate) return profile;
    const due = new Date(profile.dueDate + "T00:00:00");
    const todayStart = new Date(new Date().toDateString());
    if (isNaN(due.getTime()) || due >= todayStart) return profile; // pas encore passée
    let childName = "";
    try {
      const rows = await supabaseFetchChildren(sess.user.id, sess.access_token);
      const match = rows.find((r) => r.birthdate === profile.dueDate);
      childName = match?.name || "";
    } catch (e) { /* pas grave si on ne trouve pas le nom, le message restera générique */ }
    try {
      await supabaseUpdateProfile(sess.user.id, {
        due_date: null, birth_announcement_pending: true, birth_announcement_name: childName || null,
      }, sess.access_token);
    } catch (e) { return profile; } // si la mise à jour échoue, on ne change rien localement non plus
    return { ...profile, dueDate: "", birthAnnouncementPending: true, birthAnnouncementName: childName };
  };

  // Recharge le profil depuis Supabase et met à jour l'état userProfile de l'app. Nécessaire après
  // l'enregistrement du profil d'onboarding (composant standalone) car la page "Mon profil" qui
  // s'affiche ensuite est une AUTRE instance du composant, qui repart de userProfile — sans ce
  // rechargement, elle affichait des champs vides même si tout avait bien été sauvegardé côté serveur.
  // Efface le message de félicitations de naissance après son premier affichage, pour qu'il
  // n'apparaisse plus à la prochaine connexion.
  const dismissBirthAnnouncement = async () => {
    setUserProfile((p) => (p ? { ...p, birthAnnouncementPending: false } : p));
    if (!session) return;
    try {
      await supabaseUpdateProfile(session.user.id, { birth_announcement_pending: false }, session.access_token);
    } catch (e) { /* pas grave si ça échoue, ça reste réglé localement pour cette session */ }
  };

  const refreshUserProfile = async () => {
    if (!session) return;
    try {
      const row = await supabaseFetchProfile(session.user.id, session.access_token);
      if (row) {
        let mapped = mapProfileRow(row);
        mapped = await checkDueDateTransition(session, mapped);
        setUserProfile(mapped);
      }
    } catch (e) { /* on garde le profil actuel si le rechargement échoue */ }
  };

  const applySession = async (sess, profileRow) => {
    setSession(sess);
    setHasProfile(true);
    // Le statut membre est déterminé à partir du profil Supabase (présence d'une date d'ancrage de
    // facturation, fixée une seule fois par becomeMember() et jamais effacée ensuite), pas d'un
    // simple indicateur de session — sinon le statut membre se perdait à chaque nouvelle connexion
    // (session locale toute neuve, sans l'indicateur), obligeant la personne à tout ressaisir.
    // Le compte admin n'a PAS d'accès membre forcé — il suit exactement le même cheminement que
    // n'importe quel compte (non-membre → abonnement → membre) pour pouvoir tester ce parcours.
    setIsMember(!!profileRow?.billing_anchor_date);

    let link = null;
    try { link = await supabaseGetPartnerLink(sess.user.id, sess.access_token); } catch { /* pas de lien, on continue normalement */ }
    setPartnerLink(link);
    supabaseGetOwnerLink(sess.user.id, sess.access_token).then(setOwnerLink).catch(() => {});

    const dataOwnerId = link ? link.owner_user_id : sess.user.id;

    if (link) {
      // On consulte le compte d'un·e partenaire en lecture seule : on va chercher SON profil (grossesse,
      // enfants, etc.) plutôt que le nôtre, qui serait vide puisqu'on n'a pas créé nos propres données.
      try {
        const ownerProfileRow = await supabaseFetchProfile(dataOwnerId, sess.access_token);
        if (ownerProfileRow) setUserProfile(mapProfileRow(ownerProfileRow));
      } catch { /* on garde le profil vide plutôt que de bloquer l'app */ }
    } else if (profileRow) {
      const mapped = mapProfileRow(profileRow);
      setUserProfile(mapped);
      if (profileRow.language) setLang(profileRow.language);
      checkDueDateTransition(sess, mapped).then((updated) => {
        if (updated.birthAnnouncementPending) setUserProfile(updated);
      });
    }

    supabaseFetchChildren(dataOwnerId, sess.access_token)
      .then((rows) => setChildren(rows.map(mapChildRow)))
      .catch(() => {}); // en cas d'échec, on garde la liste vide plutôt que de bloquer l'app
  };

  // Analyse l'URL pour voir si on arrive via le lien de confirmation envoyé par courriel
  // (Supabase ajoute access_token/refresh_token/type dans le fragment #... de l'adresse)
  const parseHashSession = () => {
    if (typeof window === "undefined") return null;
    const hash = window.location.hash;
    if (!hash || !hash.includes("access_token")) return null;
    const params = new URLSearchParams(hash.slice(1));
    const access_token = params.get("access_token");
    const refresh_token = params.get("refresh_token");
    const type = params.get("type");
    if (!access_token) return null;
    return { access_token, refresh_token, type };
  };

  // Au chargement de l'app : on regarde d'abord si on arrive via un lien de confirmation de courriel,
  // sinon on tente de restaurer la session déjà ouverte (localStorage)
  useEffect(() => {
    (async () => {
      const fromLink = parseHashSession();
      if (fromLink) {
        try {
          const user = await supabaseGetUser(fromLink.access_token);
          const sessionToStore = { access_token: fromLink.access_token, refresh_token: fromLink.refresh_token, user, isMember: false };
          saveLocalSession(sessionToStore);
          window.history.replaceState(null, "", window.location.pathname + window.location.search); // nettoie l'adresse
          if (fromLink.type === "signup") { setJustSignedUp(true); setActive("profil"); }
          if (fromLink.type === "recovery") { setNeedsPasswordReset(true); }
          const profileRow = await supabaseFetchProfile(user.id, fromLink.access_token).catch(() => null);
          await applySession(sessionToStore, profileRow);
          setCheckingSession(false);
          return;
        } catch (e) {
          window.history.replaceState(null, "", window.location.pathname + window.location.search);
          // on retombe sur la restauration normale ci-dessous si le lien est invalide/expiré
        }
      }

      const stored = loadLocalSession();
      if (!stored?.access_token) { setCheckingSession(false); return; }
      try {
        const user = await supabaseGetUser(stored.access_token);
        const profileRow = await supabaseFetchProfile(user.id, stored.access_token).catch(() => null);
        await applySession(stored, profileRow);
      } catch (e) {
        // Le jeton d'accès a probablement expiré : on tente un rafraîchissement silencieux
        if (stored.refresh_token) {
          try {
            const refreshed = await supabaseRefreshSession(stored.refresh_token);
            const merged = { access_token: refreshed.access_token, refresh_token: refreshed.refresh_token, user: refreshed.user, isMember: stored.isMember };
            saveLocalSession(merged);
            const profileRow = await supabaseFetchProfile(refreshed.user.id, refreshed.access_token).catch(() => null);
            await applySession(merged, profileRow);
          } catch (e2) {
            clearLocalSession();
          }
        } else {
          clearLocalSession();
        }
      }
      setCheckingSession(false);
    })();
  }, []);

  // Au retour depuis Stripe Checkout (après paiement ou annulation) : l'adresse contient
  // ?checkout=success ou ?checkout=cancelled. Le webhook Stripe a déjà mis à jour le profil Supabase
  // à ce moment-là (ou est sur le point de le faire) — on relit donc le profil quelques fois avec un
  // court délai, le temps que billing_anchor_date apparaisse, plutôt que de se fier à un état local.
  // Même chose au retour du Customer Portal (?portal=return) : la personne peut y avoir annulé,
  // réactivé ou changé de carte — sans ce rafraîchissement, l'app continuerait d'afficher son
  // ancien statut en mémoire et le bandeau d'annulation n'apparaîtrait jamais.
  const checkoutReturnHandled = useRef(false);
  useEffect(() => {
    if (checkingSession || checkoutReturnHandled.current) return;
    if (typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    const checkoutResult = params.get("checkout");
    const portalResult = params.get("portal");
    if (!checkoutResult && !portalResult) return;
    checkoutReturnHandled.current = true;
    window.history.replaceState(null, "", window.location.pathname);

    if (!session?.access_token) return;

    if (portalResult) {
      // Simple relecture du profil — pas besoin d'attendre billing_anchor_date puisqu'il existait
      // déjà avant d'aller sur le portail ; on veut juste le statut/la date d'accès à jour.
      (async () => {
        for (let attempt = 0; attempt < 4; attempt++) {
          try {
            const profileRow = await supabaseFetchProfile(session.user.id, session.access_token);
            if (profileRow) { await applySession(session, profileRow); return; }
          } catch (e) { /* on retente, le webhook peut prendre un instant */ }
          await new Promise((r) => setTimeout(r, 1200));
        }
      })();
      return;
    }

    if (checkoutResult !== "success") return;

    (async () => {
      for (let attempt = 0; attempt < 6; attempt++) {
        try {
          const profileRow = await supabaseFetchProfile(session.user.id, session.access_token);
          if (profileRow?.billing_anchor_date) {
            await applySession(session, profileRow);
            setJustBecameMember(true);
            setActive("abonnement");
            return;
          }
        } catch (e) { /* on retente, le webhook peut prendre un instant */ }
        await new Promise((r) => setTimeout(r, 1500));
      }
    })();
  }, [checkingSession, session]);

  // Appelé après une inscription ou une connexion réussie. Passe par applySession — la même logique
  // que la restauration de session au chargement de l'app — pour que la connexion via le formulaire
  // de connexion recharge elle aussi correctement le statut membre, le partage partenaire et le
  // profil complet, plutôt qu'une version incomplète qui laissait tout ça vide/à zéro.
  const handleAuthComplete = async (profileForm, authSession, isFreshSignup) => {
    if (authSession?.access_token) {
      const sessionToStore = { access_token: authSession.access_token, refresh_token: authSession.refresh_token, user: authSession.user };
      saveLocalSession(sessionToStore);
      if (isFreshSignup) { setJustSignedUp(true); setActive("profil"); }
      let profileRow = null;
      try {
        profileRow = await supabaseFetchProfile(authSession.user.id, authSession.access_token);
      } catch (e) { /* on retombe sur le formulaire saisi localement si la lecture échoue */ }
      await applySession(sessionToStore, profileRow);
      if (profileRow) return;
    }
    if (profileForm) setUserProfile(profileForm);
  };

  const becomeMember = (billingCycle, preferredCurrency) => {
    setIsMember(true);
    setJustBecameMember(true);
    setSession((prev) => {
      if (!prev) return prev;
      const updated = { ...prev, isMember: true };
      saveLocalSession(updated);
      return updated;
    });
    // La date d'ancrage (premier paiement, à la fin de l'essai gratuit) est fixée une seule fois ici —
    // toutes les dates de renouvellement futures se calculent ensuite à partir de cette date précise,
    // plutôt que de recalculer "aujourd'hui + 30 jours" à chaque visite (ce qui donnerait une date qui
    // change tout le temps au lieu de rester fixe).
    const anchorDate = new Date();
    anchorDate.setDate(anchorDate.getDate() + TRIAL_DAYS);
    const anchorDateStr = anchorDate.toISOString().slice(0, 10);
    setUserProfile((p) => (p ? {
      ...p,
      ...(billingCycle ? { billingCycle } : {}),
      ...(preferredCurrency ? { preferredCurrency } : {}),
      billingAnchorDate: anchorDateStr,
    } : p));
    if (session) {
      const updates = { billing_anchor_date: anchorDateStr };
      if (billingCycle) updates.billing_cycle = billingCycle;
      if (preferredCurrency) updates.preferred_currency = preferredCurrency;
      supabaseUpdateProfile(session.user.id, updates, session.access_token).catch(() => { /* pas grave si ça échoue, l'état local reste correct pour cette session */ });
    }
  };

  const logout = async () => {
    if (session?.access_token) await supabaseSignOut(session.access_token);
    clearLocalSession();
    setSession(null);
    setHasProfile(false);
    setIsMember(false);
    setUserProfile(null);
    setChildren([]);
    setActive("accueil");
  };

  if (checkingSession) {
    return (
      <div style={{ fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Logo height={34} />
      </div>
    );
  }

  if (needsPasswordReset) {
    return <ResetPasswordScreen lang={lang} session={session} onDone={() => setNeedsPasswordReset(false)} />;
  }

  if (!hasProfile) {
    return <ProfileGate lang={lang} onComplete={handleAuthComplete} />;
  }

  if (justSignedUp) {
    return (
      <div style={{ fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh", padding: "24px 16px" }}>
        <div style={{ maxWidth: 560, margin: "0 auto" }}>
          <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
            <Logo height={34} />
          </div>
          <ProfileSection
            lang={lang} setLang={setLang} children={children} setChildren={setChildren} userProfile={userProfile}
            session={session} justSignedUp={true} onOnboardingDone={async () => { await refreshUserProfile(); setJustSignedUp(false); setActive("profil"); }}
            standalone
          />
        </div>
      </div>
    );
  }

  const renderContent = () => {
    switch (active) {
      case "accueil": return <Home lang={lang} goTo={goTo} isMember={isMemberActive} userProfile={userProfile} children={children} session={effectiveSession} onDismissBirthAnnouncement={dismissBirthAnnouncement} isReadOnlyPartner={isReadOnlyPartner} />;
      case "conception": return <ConceptionSection lang={lang} isMember={isMemberActive} goTo={goTo} session={session} />;
      case "grossesse": return <PregnancySection lang={lang} isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} userProfile={userProfile} session={effectiveSession} />;
      case "postpartum": return <GenericSection lang={lang} sectionKey="postpartum" isMember={isMemberActive} goTo={goTo} />;
      case "dev01": return <GenericSection lang={lang} sectionKey="dev01" isMember={isMemberActive} goTo={goTo} children={children} session={session} />;
      case "alimentation": return <GenericSection lang={lang} sectionKey="alimentation" isMember={isMemberActive} goTo={goTo} />;
      case "soins": return <GenericSection lang={lang} sectionKey="soins" isMember={isMemberActive} goTo={goTo} />;
      case "sante": return <GenericSection lang={lang} sectionKey="sante" isMember={isMemberActive} goTo={goTo} />;
      case "famille": return <GenericSection lang={lang} sectionKey="famille" isMember={isMemberActive} goTo={goTo} />;
      case "mission": return <MissionSection lang={lang} />;
      case "abonnement": return <AbonnementUnified lang={lang} isMember={isMember} goTo={goTo} onBecomeMember={becomeMember} userProfile={userProfile} session={session} onUpdateProfile={(updates) => setUserProfile((p) => (p ? { ...p, ...updates } : p))} isReadOnlyPartner={isReadOnlyPartner} partnerLink={partnerLink} setPartnerLink={setPartnerLink} />;
      case "profil": return <ProfileSection lang={lang} setLang={setLang} children={children} setChildren={setChildren} userProfile={userProfile} onLogout={logout} session={session} justSignedUp={justSignedUp} onOnboardingDone={async () => { await refreshUserProfile(); setJustSignedUp(false); }} isMember={isMember} onBecomeMember={isMember ? () => setIsMember(false) : becomeMember} goTo={goTo} ownerLink={ownerLink} setOwnerLink={setOwnerLink} partnerLink={partnerLink} setPartnerLink={setPartnerLink} onUpdateProfile={(updates) => setUserProfile((p) => (p ? { ...p, ...updates } : p))} />;
      case "dietitian": return <DietitianChat lang={lang} isMember={isMemberActive} goTo={goTo} userEmail={userProfile?.email} userFirstName={userProfile?.firstName} lastMenuRequestAt={userProfile?.lastMenuRequestAt} session={session} onUpdateProfile={(updates) => setUserProfile((p) => (p ? { ...p, ...updates } : p))} />;
      case "contact": return <ContactSection lang={lang} />;
      default: return null;
    }
  };

  return (
    <div style={{ fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh", color: COLORS.text }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; -webkit-font-smoothing: antialiased; }
        body { margin: 0; }
        ::-webkit-scrollbar { height: 6px; width: 6px; }
        ::-webkit-scrollbar-thumb { background: ${COLORS.line}; border-radius: 10px; }
        button { font-family: inherit; }
        button:focus-visible, input:focus-visible { outline: 2px solid ${COLORS.ochre}; outline-offset: 2px; }

        .page-shell { max-width: 880px; margin: 0 auto; padding: 28px 24px 64px; }

        @media (max-width: 900px) {
          .page-shell { padding: 16px 16px 48px; }
        }
        @media (max-width: 560px) {
          .hero-illu { display: none; }
        }
      `}</style>

      {/* Header */}
      <header style={{
        background: "rgba(247,244,238,0.82)", backdropFilter: "blur(14px)", WebkitBackdropFilter: "blur(14px)",
        borderBottom: `1px solid ${COLORS.line}`, position: "sticky", top: 0, zIndex: 30,
      }}>
        <div style={{ maxWidth: 1180, margin: "0 auto", padding: "14px 24px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setNavOpen((v) => !v)}
              style={{ background: "none", border: "none", cursor: "pointer", padding: 0, display: "flex", alignItems: "center", gap: 8 }}
              aria-label="Me My Baby menu"
            >
              <Logo height={36} />
            </button>
            <NavDropdown open={navOpen} active={active} goTo={goTo} lang={lang} onClose={() => setNavOpen(false)} onLogout={session ? logout : null} />
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <GlobalSearch lang={lang} goTo={goTo} compact />
            {/* Indicateur de langue — purement informatif, se change dans Mon profil */}
            <div style={{
              display: "flex", alignItems: "center", gap: 6, background: COLORS.card,
              border: `1px solid ${COLORS.line}`, borderRadius: 999, padding: "7px 14px",
              fontSize: 13, fontWeight: 600, color: COLORS.muted,
            }}>
              <Globe size={15} />
              {lang === "fr" ? "FR" : lang === "en" ? "EN" : "ES"}
            </div>
          </div>
        </div>
      </header>

      {session && userProfile?.subscriptionStatus === "payment_failed" && (
        <div style={{
          background: "#B3261E", color: "#fff", padding: "12px 20px", display: "flex",
          alignItems: "center", justifyContent: "center", gap: 12, flexWrap: "wrap", textAlign: "center",
        }}>
          <span style={{ fontSize: 13.5, fontWeight: 600 }}>
            {lang === "fr"
              ? "⚠️ Votre compte est bloqué — votre dernier paiement n'a pas fonctionné. Mettez à jour votre mode de paiement pour retrouver l'accès."
              : lang === "es"
              ? "⚠️ Tu cuenta está bloqueada — tu último pago no funcionó. Actualiza tu método de pago para recuperar el acceso."
              : "⚠️ Your account is blocked — your last payment didn't go through. Update your payment method to regain access."}
          </span>
          <button onClick={() => goTo("abonnement")} style={{
            background: "#fff", color: "#B3261E", border: "none", padding: "6px 16px",
            borderRadius: 999, fontWeight: 700, fontSize: 12.5, cursor: "pointer", flexShrink: 0,
          }}>
            {lang === "fr" ? "Mettre à jour le paiement" : lang === "es" ? "Actualizar el pago" : "Update payment"}
          </button>
        </div>
      )}

      {session && userProfile?.subscriptionStatus === "cancelled" && (
        <div style={{
          background: "#B3261E", color: "#fff", padding: "12px 20px", display: "flex",
          alignItems: "center", justifyContent: "center", gap: 12, flexWrap: "wrap", textAlign: "center",
        }}>
          <span style={{ fontSize: 13.5, fontWeight: 600 }}>
            {cancelledAndExpired
              ? (lang === "fr"
                  ? "⚠️ Votre compte est annulé — vous n'avez plus accès aux fonctionnalités. Remettez votre abonnement en vigueur pour y accéder à nouveau."
                  : lang === "es"
                  ? "⚠️ Tu cuenta está cancelada — ya no tienes acceso a las funciones. Reactiva tu suscripción para volver a acceder."
                  : "⚠️ Your account is cancelled — you no longer have access to the features. Reactivate your subscription to regain access.")
              : (lang === "fr"
                  ? `⚠️ Demande d'annulation en cours — votre compte sera annulé le ${new Date(userProfile.subscriptionAccessUntil + "T00:00:00").toLocaleDateString("fr-CA", { day: "numeric", month: "long", year: "numeric" })}. Vous perdrez alors l'accès à toutes les fonctionnalités. Remettez votre abonnement en vigueur pour l'annuler.`
                  : lang === "es"
                  ? `⚠️ Solicitud de cancelación en curso — tu cuenta se cancelará el ${new Date(userProfile.subscriptionAccessUntil + "T00:00:00").toLocaleDateString("es-MX", { day: "numeric", month: "long", year: "numeric" })}. Perderás entonces el acceso a todas las funciones. Reactiva tu suscripción para cancelar esto.`
                  : `⚠️ Cancellation request in progress — your account will be cancelled on ${new Date(userProfile.subscriptionAccessUntil + "T00:00:00").toLocaleDateString("en-CA", { day: "numeric", month: "long", year: "numeric" })}. You will then lose access to all features. Reactivate your subscription to undo this.`)}
          </span>
          <button onClick={() => goTo("abonnement")} style={{
            background: "#fff", color: "#B3261E", border: "none", padding: "6px 16px",
            borderRadius: 999, fontWeight: 700, fontSize: 12.5, cursor: "pointer", flexShrink: 0,
          }}>
            {lang === "fr" ? "Remettre en vigueur" : lang === "es" ? "Reactivar" : "Reactivate"}
          </button>
        </div>
      )}

      <div className="page-shell">
        {active !== "accueil" && active !== "abonnement" && (
          <button
            onClick={goBack}
            aria-label={lang === "fr" ? "Retour" : lang === "es" ? "Volver" : "Back"}
            style={{
              display: "inline-flex", alignItems: "center", gap: 6, background: "none", border: "none",
              cursor: "pointer", padding: "6px 0", marginBottom: 14, color: COLORS.teal,
              fontFamily: UI_FONT, fontSize: 14, fontWeight: 700,
            }}
          >
            <ArrowLeft size={18} />
            {lang === "fr" ? "Retour" : lang === "es" ? "Volver" : "Back"}
          </button>
        )}
        {renderContent()}
      </div>

      <footer style={{ borderTop: `1px solid ${COLORS.line}`, padding: "24px 20px", textAlign: "center" }}>
        <div style={{ marginBottom: 8, display: "flex", justifyContent: "center" }}>
          <Logo height={26} />
        </div>
        <p style={{ fontSize: 12.5, color: COLORS.muted, margin: 0 }}>
          {lang === "fr" ? "Me My Baby — de la conception à 5 ans. Le contenu de cette application est informatif et ne remplace pas l'avis d'un professionnel de la santé." : "Me My Baby — from conception to age 5. Content in this app is informational and does not replace advice from a healthcare professional."}
        </p>
      </footer>

      {justBecameMember && (
        <div onClick={() => { setJustBecameMember(false); setActive("accueil"); }} style={{
          position: "fixed", inset: 0, zIndex: 300, background: "rgba(47,72,88,0.5)",
          display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
        }}>
          <div onClick={(e) => e.stopPropagation()} style={{
            background: "#fff", borderRadius: 20, maxWidth: 400, width: "100%",
            padding: "30px 26px", textAlign: "center", boxShadow: "0 20px 50px rgba(0,0,0,0.3)",
          }}>
            <div style={{ fontSize: 42, marginBottom: 10 }}>🎉</div>
            <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 21, color: COLORS.teal, margin: "0 0 10px" }}>
              {lang === "fr" ? "Bienvenue dans la communauté !" : lang === "es" ? "¡Bienvenida a la comunidad!" : "Welcome to the community!"}
            </h3>
            <p style={{ fontSize: 13.5, color: COLORS.text, lineHeight: 1.6, margin: "0 0 6px" }}>
              {lang === "fr" ? "Vous êtes maintenant membre de Me My Baby." : lang === "es" ? "Ahora eres miembro de Me My Baby." : "You're now a Me My Baby member."}
            </p>
            <p style={{ fontSize: 12.5, color: COLORS.muted, lineHeight: 1.6, margin: "0 0 24px" }}>
              {lang === "fr" ? "Vous avez maintenant accès à toutes les fonctionnalités." : lang === "es" ? "Ahora tienes acceso a todas las funcionalidades." : "You now have access to all features."}
            </p>
            <button onClick={() => { setJustBecameMember(false); setActive("accueil"); }} style={{
              background: COLORS.teal, color: "#fff", border: "none", padding: "12px 26px", borderRadius: 999,
              fontWeight: 700, fontSize: 14, cursor: "pointer",
            }}>
              {lang === "fr" ? "Commencer à naviguer" : lang === "es" ? "Empezar a explorar" : "Start browsing"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
